import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> splitIntoFibonacci(String num) {
        List<Integer> result = new ArrayList<>();
        backtrack(num, 0, result);
        return result;
    }

    private boolean backtrack(String num, int index, List<Integer> result) {
        if (index == num.length() && result.size() >= 3) {
            return true;
        }

        for (int i = index; i < num.length(); i++) {
            if (i > index && num.charAt(index) == '0') {
                break;
            }

            String sub = num.substring(index, i + 1);
            if (sub.length() > 10) {
                break;
            }

            try {
                long val = Long.parseLong(sub);
                if (val > Integer.MAX_VALUE) {
                    break;
                }

                if (result.size() >= 2) {
                    long sum = (long) result.get(result.size() - 1) + (long) result.get(result.size() - 2);
                    if (sum != val) {
                        continue;
                    }
                }

                result.add((int) val);
                if (backtrack(num, i + 1, result)) {
                    return true;
                }
                result.remove(result.size() - 1);
            } catch (NumberFormatException e) {
                break;
            }
        }

        return false;
    }
}

