            adj.add(new ArrayList<>());
        }

        for (int i = 0; i < routes.length; i++) {
            for (int j = i + 1; j < routes.length; j++) {
                if (intersect(routes[i], routes[j])) {
                    adj.get(i).add(j);
                    adj.get(j).add(i);
                }
            }
        }

        List<Integer> busStopsToRoutes = new ArrayList<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                busStopsToRoutes.add(stop);
            }
        }

        Set<Integer> sourceStops = new HashSet<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                if (stop == source) {
                    sourceStops.add(i);
                    break;
                }
            }
        }

        if (sourceStops.isEmpty()) {
            return -1;
        }

        Queue<Integer> queue = new ArrayDeque<>(sourceStops);
        Set<Integer> visitedRoutes = new HashSet<>(sourceStops);
        int buses = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int routeIndex = queue.poll();
                for (int nextRouteIndex : adj.get(routeIndex)) {
                    if (!visitedRoutes.contains(nextRouteIndex)) {
                        boolean targetFound = false;
                        for (int stop : routes[nextRouteIndex]) {
                            if (stop == target) {
                                return buses;
                            }
                        }
                        visitedRoutes.add(nextRouteIndex);
                        queue.offer(nextRouteIndex);
                    }
                }
            }
            buses++;
        }

        return -1;
    }

    private boolean intersect(int[] route1, int[] route2) {
        Set<Integer> set1 = new HashSet<>();
        for (int stop : route1) {
            set1.add(stop);
        }
        for (int stop : route2) {
            if (set1.contains(stop)) {
                return true;
            }
        }
        return false;
    }
}

