                for (TreeNode l : left) {
                    for (TreeNode r : right) {
                        TreeNode root = new TreeNode(0);
                        root.left = l;
                        root.right = r;
                        dp[i].add(root);
                    }
                }
            }
        }

        return dp[n];
    }
}

