public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k == 0) return 1.0;
        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        double sum = 1.0;
        for (int i = 1; i <= n; i++) {
            dp[i] = sum / w;
            if (i > k) {
                sum -= dp[i - w];
            }
            sum += dp[i];
        }
