import java.util.ArrayList;
import java.util.List;
public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();
        for (int i = 1; i < n - 1; i++) {
            String left = s.substring(1, i);
            String right = s.substring(i, n - 1);
            List<String> leftList = generatePossibilities(left);
            List<String> rightList = generatePossibilities(right);
            for (String l : leftList) {
                for (String r : rightList) {
                    result.add("(" + l + ", " + r + ")");
                }
            }
        }
        return result;
    }

    private List<String> generatePossibilities(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();
        for (int i = 1; i < n; i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);
            if (isValid(left) && isValid(right)) {
                result.add(left + "." + right);
            }
        }
        if (isValid(s)) {
            result.add(s);
        }
        return result;
    }

    private boolean isValid(String s) {
        if (s.length() > 1 && s.startsWith("0")) {
            return false;
        }
        if (s.contains(".") && s.split("\\.").length > 2) {
            return false;
        }
        if (s.contains(".") && s.endsWith(".")) {
            return false;
        }
        if (s.isEmpty()) {
            return false;
        }
        return true;
    }
}

