// #Medium #Array #String #Prefix_Sum #2022_09_02_Time_7_ms_(98.86%)_Space_92_MB_(72.81%)
public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int m = 0, p = 0, g = 0;
        int lastM = 0, lastP = 0, lastG = 0;
        int totalTime = 0;

        for (int i = 0; i < garbage.length; i++) {
            String houseGarbage = garbage[i];
            for (char c : houseGarbage.toCharArray()) {
                if (c == 'M') {
                    m++;
                } else if (c == 'P') {
                    p++;
                } else {
                    g++;
                }
            }

            if (m > 0 && i >= lastM) {
                totalTime += travel[i - lastM];
                lastM = i;
            }
            if (p > 0 && i >= lastP) {
                totalTime += travel[i - lastP];
                lastP = i;
            }
            if (g > 0 && i >= lastG) {
                totalTime += travel[i - lastG];
                lastG = i;
            }
        }

        return totalTime;
    }
}

