// #Medium #Math #Two_Pointers #Brainteaser #2022_09_14_Time_0_ms_(100.00%)_Space_40.6_MB_(75.27%)
public class Solution {
    public boolean isStrictlyPalindromic(int n) {
        if (n <= 1) {
            return false;
        }

        for (int base = 2; base <= n - 2; base++) {
            String representation = convertToBase(n, base);
            if (!isPalindrome(representation)) {
                return false;
            }
        }

        return true;
    }

    private String convertToBase(int n, int base) {
        StringBuilder sb = new StringBuilder();
        while (n > 0) {
            int remainder = n % base;
            sb.append(remainder);
            n /= base;
        }
        return sb.reverse().toString();
    }

    private boolean isPalindrome(String s) {
        int left = 0;
        int right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

