public class Solution {
    public long kSum(int[] nums, int k) {
        int n = nums.length;
        long[] sums = new long[1 << n];
        for (int i = 0; i < (1 << n); i++) {
            long sum = 0;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    sum += nums[j];
                }
            }
            sums[i] = sum;
        }
        Arrays.sort(sums);
        return sums[sums.length - k];
    }
}

