public class Solution {
    public int edgeScore(int[] edges) {
        int n = edges.length;
        int[] inDegree = new int[n];
        for (int edge : edges) {
            inDegree[edge]++;
        }
        int maxScore = -1;
        int result = -1;
        for (int i = 0; i < n; i++) {
            int score = inDegree[i];
            if (score > maxScore) {
                maxScore = score;
                result = i;
            } else if (score == maxScore && i < result) {
                result = i;
            }
        }
        return result;
    }
}

