public class Solution {
    public int minimumOperations(int[] nums) {
        int operations = 0;
        while (true) {
            int minPositive = Integer.MAX_VALUE;
            for (int num : nums) {
                if (num > 0) {
                    minPositive = Math.min(minPositive, num);
                }
            }
            if (minPositive == Integer.MAX_VALUE) {
                break;
            }
            int x = minPositive;
            operations++;
            for (int i = 0; i < nums.length; i++) {
                if (nums[i] > 0) {
                    nums[i] -= x;
                }
            }
        }
        return operations;
    }
}

