import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
public class Solution {
    public int distinctNames(String[] ideas) {
        Map<String, Set<String>> group = new HashMap<>();
        for (String idea : ideas) {
            String key = idea.substring(1);
            group.computeIfAbsent(key, k -> new HashSet<>()).add(idea.charAt(0));
        }

        int count = 0;
        for (Map.Entry<String, Set<String>> entry1 : group.entrySet()) {
            for (Map.Entry<String, Set<String>> entry2 : group.entrySet()) {
                if (entry1.getKey().equals(entry2.getKey())) {
                    continue;
                }

                Set<String> set1 = entry1.getValue();
                Set<String> set2 = entry2.getValue();
                int intersection = 0;
                for (String c1 : set1) {
                    if (set2.contains(c1)) {
                        intersection++;
                    }
                }

                count += (set1.size() - intersection) * (set2.size() - intersection);
            }
        }

        return count;
    }
}

