public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        Arrays.sort(nums);
        int minVal = nums[0];
        boolean possible = true;
        for (int num : numsDivide) {
            if (num % minVal != 0) {
                possible = false;
                break;
            }
        }
        if (possible) {
            return 0;
        }
        int deletions = 0;
        int i = 0;
        while (i < nums.length) {
            int currentMin = nums[i];
            boolean valid = true;
            for (int num : numsDivide) {
                if (num % currentMin != 0) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return deletions;
            }
            deletions++;
            int j = i + 1;
            while (j < nums.length && nums[j] == nums[i]) {
                j++;
            }
            i = j;
        }
        return -1;
    }
}

