public class Solution {
    public int longestIdealString(String s, int k) {
        int[] dp = new int[26];
        for (char c : s.toCharArray()) {
            int index = c - 'a';
            int maxLen = 1;
            for (int i = 0; i < 26; i++) {
                if (Math.abs(index - i) <= k) {
                    maxLen = Math.max(maxLen, dp[i] + 1);
                }
            }
            dp[index] = maxLen;
        }
        int result = 0;
        for (int len : dp) {
            result = Math.max(result, len);
        }
        return result;
    }
}

