public class Solution {
    public int fillCups(int[] amount) {
        Arrays.sort(amount);
        int ans = 0;
        int i = 0;
        int j = amount.length - 1;
        while (i < j) {
            if (amount[i] == amount[j]) {
                amount[i]--;
                amount[j]--;
                ans++;
            } else {
                amount[j]--;
                amount[i]++;
                ans++;
            }
            if (amount[i] > amount[j]) {
                int temp = amount[i];
                amount[i] = amount[j];
                amount[j] = temp;
            }
        }
        if (amount[0] > 0) {
            ans++;
        }
        return ans;
    }
}

