// #Medium #Array #Dynamic_Programming #2022_08_16_Time_7_ms_(81.82%)_Space_93.5_MB_(9.09%)
public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;
        if (n < 2) {
            return false;
        }

        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        for (int i = 2; i <= n; i++) {
            if (nums[i - 2] == nums[i - 1]) {
                if (dp[i - 2]) {
                    dp[i] = true;
                    continue;
                }
            }

            if (i >= 3 && nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1]) {
                if (dp[i - 3]) {
                    dp[i] = true;
                    continue;
                }
            }

            if (i >= 3 && nums[i - 2] - nums[i - 3] == 1 && nums[i - 1] - nums[i - 2] == 1) {
                if (dp[i - 3]) {
                    dp[i] = true;
                    continue;
                }
            }
        }

        return dp[n];
    }
}

