import java.util.Arrays;

public class Solution {
    public int maximumGroups(int[] grades) {
        Arrays.sort(grades);
        int n = grades.length;
        long currentSum = 0;
        int groupCount = 0;
        long currentSize = 0;
        for (int i = 0; i < n; i++) {
            currentSum += grades[i];
            currentSize++;
            if (i + 1 < n) {
                long nextSum = currentSum;
                long nextSize = currentSize;
                int j = i + 1;
                while (j < n) {
                    nextSum += grades[j];
                    nextSize++;
                    if (nextSum > currentSum && nextSize > currentSize) {
                        currentSum = nextSum;
                        currentSize = nextSize;
                        groupCount++;
                        break;
                    }
                    j++;
                }
                if (j == n) {
                    break;
                }
            } else {
                groupCount++;
            }
        }
        return groupCount;
    }
}

