            if (Character.isLowerCase(c)) {
                hasLower[c - 'a'] = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper[c - 'A'] = true;
            }
        }

        char greatest = ' ';
        for (int i = 25; i >= 0; i--) {
            if (hasLower[i] && hasUpper[i]) {
                greatest = (char) ('A' + i);
                break;
            }
        }

        return String.valueOf(greatest);
