        int minOperations = Integer.MAX_VALUE;
        int currentOperations = 0;

        for (int i = 0; i < n; i++) {
            if (blocks.charAt(i) == 'W') {
                currentOperations++;
            }

            if (i >= k) {
                if (blocks.charAt(i - k) == 'W') {
                    currentOperations--;
