        negativeDiffs.sort((a, b) -> b - a);

        int i = 0;
        int j = 0;

        while (i < positiveDiffs.size() && j < negativeDiffs.size()) {
            int positiveDiff = positiveDiffs.get(i);
            int negativeDiff = negativeDiffs.get(j);

            if (Math.abs(positiveDiff) > Math.abs(negativeDiff)) {
                operations += (long) Math.ceil((double) positiveDiff / 2);
                i++;
            } else {
                operations += (long) Math.ceil((double) Math.abs(negativeDiff) / 2);
                j++;
            }
        }

        while (i < positiveDiffs.size()) {
            operations += (long) Math.ceil((double) positiveDiffs.get(i) / 2);
            i++;
        }

        while (j < negativeDiffs.size()) {
            operations += (long) Math.ceil((double) Math.abs(negativeDiffs.get(j)) / 2);
