public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int m = f.length;

        // Sort robots by x-position in ascending order
        Integer[] robots = robot.toArray(new Integer[0]);
        Arrays.sort(robots);

        // Sort factories by x-position in ascending order
        Arrays.sort(f, (a, b) -> Integer.compare(a[0], b[0]));

        long totalDistance = 0;
        int[] factoryCapacity = new int[m];
        for (int i = 0; i < m; i++) {
            factoryCapacity[i] = f[i][1];
        }

        for (int i = 0; i < n; i++) {
            int bestFactory = -1;
            long minDistance = Long.MAX_VALUE;

            for (int j = 0; j < m; j++) {
                if (factoryCapacity[j] > 0) {
                    long distance = Math.abs(robots[i] - f[j][0]);
                    if (distance < minDistance) {
                        minDistance = distance;
                        bestFactory = j;
                    }
                }
            }

            if (bestFactory != -1) {
                totalDistance += minDistance;
                factoryCapacity[bestFactory]--;
            } else {
                // If no factory has capacity, find the closest one regardless of capacity
                long minDistanceToAny = Long.MAX_VALUE;
                int closestFactory = -1;
                for (int j = 0; j < m; j++) {
                    long distance = Math.abs(robots[i] - f[j][0]);
                    if (distance < minDistanceToAny) {
                        minDistanceToAny = distance;
                        closestFactory = j;
                    }
                }
                totalDistance += minDistanceToAny;
            }
        }

        return totalDistance;
    }
}

