import java.util.List;
public class Solution {
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        List<Pair> pairs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pairs.add(new Pair(nums[i], cost[i]));
        }
        pairs.sort(Comparator.comparingInt(p -> p.num));
        long totalCost = 0;
        long currentSum = 0;
        int totalWeight = 0;
        int median = 0;
        for (Pair pair : pairs) {
            currentSum += (long) pair.num * pair.cost;
            totalWeight += pair.cost;
        }
        median = findMedian(nums, cost);
        for (int i = 0; i < n; i++) {
            totalCost += (long) Math.abs(nums[i] - median) * cost[i];
        }
        return totalCost;
    }

    private int findMedian(int[] nums, int[] cost) {
        int n = nums.length;
        List<Pair> pairs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pairs.add(new Pair(nums[i], cost[i]));
        }
        pairs.sort(Comparator.comparingInt(p -> p.num));
        long totalWeight = 0;
        for (Pair pair : pairs) {
            totalWeight += pair.cost;
        }
        long currentWeight = 0;
        for (Pair pair : pairs) {
            currentWeight += pair.cost;
            if (currentWeight >= totalWeight / 2) {
                return pair.num;
            }
        }
        return pairs.get(n - 1).num;
    }

    static class Pair {
        int num;
        int cost;

        public Pair(int num, int cost) {
            this.num = num;
            this.cost = cost;
        }
    }
