                    }
                }
                if (currentQuality > maxQuality) {
                    maxQuality = currentQuality;
                    bestCoordinate[0] = x;
                    bestCoordinate[1] = y;
                } else if (currentQuality == maxQuality) {
                    if (x < bestCoordinate[0]) {
                        bestCoordinate[0] = x;
                        bestCoordinate[1] = y;
                    } else if (x == bestCoordinate[0] && y < bestCoordinate[1]) {
                        bestCoordinate[1] = y;
                    }
                }
            }
        }
