import java.util.LinkedList;
import java.util.Objects;
import java.util.Queue;
public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        Queue<Integer> studentQueue = new LinkedList<>();
        for (int student : students) {
            studentQueue.offer(student);
        }

        int sandwichIndex = 0;
        int unableToEat = 0;

        while (!studentQueue.isEmpty()) {
            int studentPreference = studentQueue.peek();
            if (studentPreference == sandwiches[sandwichIndex]) {
                studentQueue.poll();
                sandwichIndex++;
            } else {
                studentQueue.offer(studentQueue.poll());

                boolean foundAlternative = false;
                for (int i = 0; i < studentQueue.size() - 1; i++) {
                    int temp = studentQueue.poll();
                    if (temp != sandwiches[sandwichIndex]) {
                        studentQueue.offer(temp);
                    } else {
                        studentQueue.offer(temp);
                        foundAlternative = true;
                        break;
                    }
                }
                if (!foundAlternative) {
                    unableToEat++;
                    studentQueue.poll();
                }
            }
            if (sandwichIndex == sandwiches.length && !studentQueue.isEmpty()) {
                unableToEat += studentQueue.size();
                break;
            }
        }

        return unableToEat;
    }
}

