public class Solution {
    private static final int MOD = 1000000007;

    public int numberOfSets(int n, int k) {
        if (k == 0) {
            return 1;
        }
        if (n < k) {
            return 0;
        }

        long[][] dp = new long[n + 1][k + 1];

        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];
                for (int len = 2; len <= i; len++) {
                    dp[i][j] = (dp[i][j] + dp[i - len][j - 1]) % MOD;
                }
            }
        }

        return (int) dp[n][k];
    }
}

