public class Solution {
    public int highestScore(int[] scores, int[] ages) {
        int n = scores.length;
        int[][] dp = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], 0);
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                dp[i][j] = dp[i - 1][j];
                boolean conflict = false;
                for (int k = 1; k < i; k++) {
                    if (ages[i - 1] < ages[k - 1] && scores[i - 1] > scores[k - 1]) {
                        conflict = true;
                        break;
                    }
                }
                if (!conflict) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - 1] + scores[i - 1]);
                }
            }
        }
        int maxScore = 0;
        for (int j = 0; j <= n; j++) {
            maxScore = Math.max(maxScore, dp[n][j]);
        }
        return maxScore;
    }
}

