public class Solution {
    public List<String> alertNames(String[] keyName, String[] keyTime) {
        Map<String, List<Integer>> nameToTimes = new HashMap<>();
        for (int i = 0; i < keyName.length; i++) {
            String name = keyName[i];
            String time = keyTime[i];
            int hours = Integer.parseInt(time.substring(0, 2));
            int minutes = Integer.parseInt(time.substring(3, 5));
            int totalMinutes = hours * 60 + minutes;
            if (!nameToTimes.containsKey(name)) {
                nameToTimes.put(name, new ArrayList<>());
            }
            nameToTimes.get(name).add(totalMinutes);
        }

        List<String> alertedNames = new ArrayList<>();
        for (String name : nameToTimes.keySet()) {
            List<Integer> times = nameToTimes.get(name);
            Collections.sort(times);
            for (int i = 0; i < times.size(); i++) {
                int currentTime = times.get(i);
                int count = 0;
                for (int j = i; j < times.size(); j++) {
                    int nextTime = times.get(j);
                    if (nextTime - currentTime <= 60) {
                        count++;
                    } else {
                        break;
                    }
                }
                if (count >= 3) {
                    alertedNames.add(name);
                    break;
                }
            }
        }

        Collections.sort(alertedNames);
        return alertedNames;
    }
