public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int[] count = new int[2 * limit + 2];
        for (int i = 0; i < n / 2; i++) {
            int sum = nums[i] + nums[n - 1 - i];
            count[sum]++;
        }
        int maxFrequency = 0;
        for (int i = 1; i <= 2 * limit; i++) {
