public class Solution {
    public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        Map<String, Integer> subtreeCount = new HashMap<>();
        List<TreeNode> duplicateSubtrees = new ArrayList<>();
        serialize(root, subtreeCount, duplicateSubtrees);
        return duplicateSubtrees;
    }

    private String serialize(TreeNode node, Map<String, Integer> subtreeCount, List<TreeNode> duplicateSubtrees) {
        if (node == null) {
            return "#";
        }

        String leftSerialized = serialize(node.left, subtreeCount, duplicateSubtrees);
        String rightSerialized = serialize(node.right, subtreeCount, duplicateSubtrees);

        String subtreeString = node.val + "," + leftSerialized + "," + rightSerialized;

        subtreeCount.put(subtreeString, subtreeCount.getOrDefault(subtreeString, 0) + 1);

        if (subtreeCount.get(subtreeString) == 2) {
            duplicateSubtrees.add(node);
        }

        return subtreeString;
    }
}

