        dfs(root, values);

        if (values.size() < 2) {
            return -1;
        }

        int minVal = Integer.MAX_VALUE;
        int secondMinVal = Integer.MAX_VALUE;

        for (int val : values) {
            if (val < minVal) {
                secondMinVal = minVal;
                minVal = val;
            } else if (val < secondMinVal && val != minVal) {
                secondMinVal = val;
            }
        }

        return secondMinVal;
    }

