public class Solution {
    public int mctFromLeafValues(int[] arr) {
        Deque<Integer> stack = new ArrayDeque<>();
        int sum = 0;
        int max = Integer.MIN_VALUE;
        for (int a : arr) {
            while (!stack.isEmpty() && a > stack.peek()) {
                max = Math.max(max, stack.pop());
            }
            sum += max * a;
            stack.push(a);
