import java.util.Arrays;
public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int n = students.length;
        int m = mentors.length;
        int maxScore = 0;
        int[] assignment = new int[n];
        boolean[] used = new boolean[m];

        maxScore = solve(students, mentors, 0, assignment, used, 0);

        return maxScore;
    }

    private int solve(int[][] students, int[][] mentors, int studentIndex, int[] assignment, boolean[] used, int currentScore) {
        if (studentIndex == students.length) {
            return currentScore;
        }

        int maxScore = 0;
        for (int mentorIndex = 0; mentorIndex < mentors.length; mentorIndex++) {
            if (!used[mentorIndex]) {
                used[mentorIndex] = true;
                assignment[studentIndex] = mentorIndex;
                int compatibilityScore = calculateCompatibilityScore(students[studentIndex], mentors[mentorIndex]);
                int newScore = solve(students, mentors, studentIndex + 1, assignment, used, currentScore + compatibilityScore);
                maxScore = Math.max(maxScore, newScore);
                used[mentorIndex] = false;
            }
        }
        return maxScore;
    }

    private int calculateCompatibilityScore(int[] studentAnswers, int[] mentorAnswers) {
        int compatibilityScore = 0;
        for (int i = 0; i < studentAnswers.length; i++) {
            if (studentAnswers[i] == mentorAnswers[i]) {
                compatibilityScore++;
            }
        }
        return compatibilityScore;
    }
