public class Solution {
    public int colorTheGrid(int m, int n) {
        long MOD = 1000000007;
        if (m == 1 && n == 1) {
            return 3;
        }
        if (m == 1 && n == 2) {
            return 6;
        }
        if (m == 2 && n == 1) {
            return 6;
        }

        long[][] dp = new long[m][n];
        long[][] prevRow = new long[n];

        // Initialize the first row
        prevRow[0] = 3;
        for (int j = 1; j < n; j++) {
            prevRow[j] = (prevRow[j - 1] * 2) % MOD;
        }

        dp[0] = prevRow;

        for (int i = 1; i < m; i++) {
            long[] currentRow = new long[n];
            currentRow[0] = (dp[i - 1][0] * 2) % MOD;
            for (int j = 1; j < n; j++) {
                if (dp[i - 1][j] == dp[i - 1][j - 1]) {
                    currentRow[j] = (dp[i - 1][j] * 2) % MOD;
                } else {
                    currentRow[j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD;
                }
            }
            dp[i] = currentRow;
        }

        return (int) dp[m - 1][n - 1];
    }
