            }
            ans[i] = maxDiff;
        }
        return ans;
    }

    private void dfs(int u, int target, List<Integer> path) {
        path.add(u);
        if (u == target) {
            return;
        }
        for (int v : getChildren(u)) {
            dfs(v, target, path);
            if (path.contains(target)) {
                return;
            }
        }
    }

    private List<Integer> getChildren(int u) {
        List<Integer> children = new ArrayList<>();
        for (int i = 0; i < parents.length; i++) {
            if (parents[i] == u) {
                children.add(i);
            }
        }
        return children;
    }

    private int[] parents;
}

