// #2022_08_02_Time_45_ms_(95.58%)_Space_52.3_MB_(87.17%)
import java.util.Arrays;

public class Solution {
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[i][j] = -1;
            }
        }

        return solve(boxes, 0, n - 1, dp);
    }

    private int solve(int[] boxes, int l, int r, int[][] dp) {
        if (l > r) {
            return 0;
        }

        if (dp[l][r] != -1) {
            return dp[l][r];
        }

        int maxPoints = 0;
        for (int i = l; i <= r; i++) {
            if (boxes[i] == boxes[l]) {
                int points = (i - l + 1) * (i - l + 1);
                int prev = (i == r) ? 0 : solve(boxes, i + 1, r, dp);
                int next = (i == l) ? 0 : solve(boxes, l, i - 1, dp);
                maxPoints = Math.max(maxPoints, points + next + prev);
            }
        }

        if (maxPoints == 0) {
            for (int i = l; i <= r; i++) {
                int points = (i - l + 1) * (i - l + 1);
                int prev = (i == r) ? 0 : solve(boxes, i + 1, r, dp);
                int next = (i == l) ? 0 : solve(boxes, l, i - 1, dp);
                maxPoints = Math.max(maxPoints, points + next + prev);
            }
        }

        dp[l][r] = maxPoints;
        return maxPoints;
    }
}

