    private int calculateSubtreeSums(TreeNode node, Map<Integer, Integer> sumCounts) {
        if (node == null) {
            return 0;
        }

        int leftSum = calculateSubtreeSums(node.left, sumCounts);
        int rightSum = calculateSubtreeSums(node.right, sumCounts);

        int subtreeSum = node.val + leftSum + rightSum;

        sumCounts.put(subtreeSum, sumCounts.getOrDefault(subtreeSum, 0) + 1);

        return subtreeSum;
    }
}

