public class Solution {
    public int findMinMoves(int[] machines) {
        int total = 0;
        for (int machine : machines) {
            total += machine;
        }

        if (total % machines.length != 0) {
            return -1;
        }

        int avg = total / machines.length;
        int maxLoad = 0;
        int currentLoad = 0;
        int maxMoves = 0;

        for (int machine : machines) {
            currentLoad += machine - avg;
            maxLoad = Math.max(maxLoad, Math.abs(currentLoad));
