        int index = random.nextInt(zeroIndices.size());
        int[] flippedIndex = zeroIndices.get(index);
        zeroIndices.remove(index);
        return flippedIndex;
    }

    public void reset() {
        zeroIndices.clear();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                zeroIndices.add(new int[]{i, j});
            }
        }
    }
