// Definition for a QuadTree node.
public class Solution {
    public boolean val;
    public boolean isLeaf;
    public Node topLeft;
    public Node topRight;
    public Node bottomLeft;
    public Node bottomRight;
}

public class Solution {
    public Node intersect(Node quadTree1, Node quadTree2) {
        if (quadTree1 == null && quadTree2 == null) {
            return null;
        }
        if (quadTree1 == null) {
            return quadTree2;
        }
        if (quadTree2 == null) {
            return quadTree1;
        }

        if (quadTree1.isLeaf && quadTree2.isLeaf) {
            Node result = new Node();
            result.isLeaf = true;
            result.val = quadTree1.val || quadTree2.val;
            return result;
        }

        if (quadTree1.isLeaf) {
            return handleLeafAndNonLeaf(quadTree1, quadTree2);
        }

        if (quadTree2.isLeaf) {
            return handleLeafAndNonLeaf(quadTree2, quadTree1);
        }

        Node result = new Node();
        result.isLeaf = false;

        result.topLeft = intersect(quadTree1.topLeft, quadTree2.topLeft);
        result.topRight = intersect(quadTree1.topRight, quadTree2.topRight);
        result.bottomLeft = intersect(quadTree1.bottomLeft, quadTree2.bottomLeft);
        result.bottomRight = intersect(quadTree1.bottomRight, quadTree2.bottomRight);

        return result;
    }

    private Node handleLeafAndNonLeaf(Node leaf, Node nonLeaf) {
        if (leaf.val) {
            Node result = new Node();
            result.isLeaf = true;
            result.val = true;
            return result;
        } else {
            Node result = new Node();
            result.isLeaf = false;
            result.topLeft = intersect(leaf, nonLeaf.topLeft);
            result.topRight = intersect(leaf, nonLeaf.topRight);
            result.bottomLeft = intersect(leaf, nonLeaf.bottomLeft);
            result.bottomRight = intersect(leaf, nonLeaf.bottomRight);
            return result;
        }
    }
}

