import java.util.ArrayList;
import java.util.List;
public class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length();
        int m = key.length();
        List<Integer>[] dp = new List[m + 1];
        for (int i = 0; i <= m; i++) {
            dp[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            if (ring.charAt(i) == key.charAt(0)) {
                dp[1].add(Math.min(i, n - i));
            }
        }

        for (int i = 2; i <= m; i++) {
            List<Integer> prevSteps = dp[i - 1];
            List<Integer> currentSteps = new ArrayList<>();
            for (int step : prevSteps) {
                for (int j = 0; j < n; j++) {
                    if (ring.charAt(j) == key.charAt(i - 1)) {
                        int diff = Math.abs(j - (step % n));
                        int rotateSteps = Math.min(diff, n - diff);
                        currentSteps.add(rotateSteps + 1 + step);
                    }
                }
            }
            dp[i] = currentSteps;
        }

        int minSteps = Integer.MAX_VALUE;
        for (int steps : dp[m]) {
            minSteps = Math.min(minSteps, steps);
        }

        return minSteps;
    }
}

