// #Hard #String #Math #2022_08_10_Time_2_ms_(100.00%)_Space_42.7_MB_(26.15%)
public class Solution {
    public String nearestPalindromic(String n) {
        long self = Long.parseLong(n);
        long len = n.length();

        if (len == 1) {
            return String.valueOf(self - 1);
        }

        long prefix = Long.parseLong(n.substring(0, (len + 1) / 2));
        long[] candidates = new long[4];

        candidates[0] = createPalindrome(prefix - 1, len % 2 == 0);
        candidates[1] = createPalindrome(prefix, len % 2 == 0);
        candidates[2] = createPalindrome(prefix + 1, len % 2 == 0);

        long minDiff = Long.MAX_VALUE;
        long result = 0;

        for (long candidate : candidates) {
            if (candidate != self) {
                long diff = Math.abs(candidate - self);
                if (diff < minDiff) {
                    minDiff = diff;
                    result = candidate;
                } else if (diff == minDiff) {
                    result = Math.min(result, candidate);
                }
            }
        }

        return String.valueOf(result);
    }

    private long createPalindrome(long prefix, boolean even) {
        String prefixStr = String.valueOf(prefix);
        StringBuilder sb = new StringBuilder(prefixStr);
        String suffix = new StringBuilder(prefixStr).reverse().toString();
        if (even) {
            sb.append(suffix);
        } else {
            sb.deleteCharAt(sb.length() - 1);
            sb.append(suffix);
        }
        try {
            return Long.parseLong(sb.toString());
        } catch (NumberFormatException e) {
            return -1;
        }
    }
