// #2022_07_28_Time_3_ms_(98.66%)_Space_41.5_MB_(24.19%)
public class Solution {
    public int countArrangement(int n) {
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = i + 1;
        }
        return countArrangementHelper(nums, 0);
    }

    private int countArrangementHelper(int[] nums, int index) {
        if (index == nums.length) {
            return 1;
        }

        int count = 0;
        for (int i = index; i < nums.length; i++) {
            swap(nums, index, i);
            if (nums[index] % (index + 1) == 0 || (index + 1) % nums[index] == 0) {
                count += countArrangementHelper(nums, index + 1);
            }
            swap(nums, index, i);
        }
        return count;
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

