public class Solution {
    public int findLUSlength(String[] strs) {
        int n = strs.length;
        int maxLength = -1;

        for (int i = 0; i < n; i++) {
            boolean isSubsequenceOfOthers = false;
            for (int j = 0; j < n; j++) {
                if (i != j && isSubsequence(strs[i], strs[j])) {
                    isSubsequenceOfOthers = true;
                    break;
