public class Solution {
    public int findUnsortedSubarray(int[] nums) {
        int n = nums.length;
        int left = n, right = -1;

        int maxVal = nums[0];
        for (int i = 1; i < n; i++) {
            maxVal = Math.max(maxVal, nums[i]);
        }

        int minVal = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            minVal = Math.min(minVal, nums[i]);
        }

        for (int i = 0; i < n; i++) {
            if (nums[i] > minVal) {
                left = Math.min(left, i);
            }
            if (nums[i] < maxVal) {
                right = Math.max(right, i);
            }
        }

        if (right - left >= 0) {
            return right - left + 1;
        } else {
            return 0;
        }
    }
}

