import java.util.Arrays;
public class Solution {
    public boolean validSquare(int[] p1, int[] p2, int[] p3, int[] p4) {
        int[][] points = {p1, p2, p3, p4};
        Arrays.sort(points, (a, b) -> (a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]));

        int distSq12 = distSq(points[0], points[1]);
        int distSq13 = distSq(points[0], points[2]);
        int distSq14 = distSq(points[0], points[3]);

        if (distSq12 == 0 || distSq13 == 0 || distSq14 == 0) {
            return false;
        }

        if (distSq12 == distSq13 && distSq12 + distSq13 == distSq14) {
            int distSq23 = distSq(points[1], points[2]);
            int distSq24 = distSq(points[1], points[3]);
            int distSq34 = distSq(points[2], points[3]);

            return distSq23 == distSq34 && distSq24 == distSq34;
        }

        return false;
    }

    private int distSq(int[] p1, int[] p2) {
        return (p1[0] - p2[0]) * (p1[0] - p2[0]) + (p1[1] - p2[1]) * (p1[1] - p2[1]);
    }
}

