// #Medium #Dynamic_Programming #2022_08_10_Time_5_ms_(92.95%)_Space_43.1_MB_(36.44%)
import java.util.Arrays;
public class Solution {
    private static final int MOD = 1000000007;
    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        int[][][] dp = new int[m][n][maxMove + 1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(dp[i][j], -1);
            }
        }
        return solve(m, n, maxMove, startRow, startColumn, dp);
    }

    private int solve(int m, int n, int maxMove, int row, int col, int[][][] dp) {
        if (row < 0 || row >= m || col < 0 || col >= n) {
            return 1;
        }
        if (maxMove == 0) {
            return 0;
        }
        if (dp[row][col][maxMove] != -1) {
            return dp[row][col][maxMove];
        }

        long up = solve(m, n, maxMove - 1, row - 1, col, dp);
        long down = solve(m, n, maxMove - 1, row + 1, col, dp);
        long left = solve(m, n, maxMove - 1, row, col - 1, dp);
        long right = solve(m, n, maxMove - 1, row, col + 1, dp);

        dp[row][col][maxMove] = (int)((up + down + left + right) % MOD);
        return dp[row][col][maxMove];
    }
}

