import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public int[][] outerTrees(int[][] trees) {
        if (trees == null || trees.length <= 1) {
            return trees;
        }

        Arrays.sort(trees, (a, b) -> {
            if (a[0] == b[0]) {
                return Integer.compare(a[1], b[1]);
            }
            return Integer.compare(a[0], b[0]);
        });

        List<int[]> hull = new ArrayList<>();
        for (int[] tree : trees) {
            while (hull.size() >= 2 && crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), tree) <= 0) {
                hull.remove(hull.size() - 1);
            }
            hull.add(tree);
        }

        int lowerSize = hull.size();
        for (int i = trees.length - 2; i >= 0; i--) {
            int[] tree = trees[i];
            while (hull.size() > lowerSize && crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), tree) <= 0) {
                hull.remove(hull.size() - 1);
            }
            hull.add(tree);
        }

        hull.remove(hull.size() - 1);

        return hull.toArray(new int[hull.size()][2]);
    }

    private int crossProduct(int[] o, int[] a, int[] b) {
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
    }
}

