// #Hard #Dynamic_Programming #2022_08_03_Time_11_ms_(98.55%)_Space_41.6_MB_(87.84%)
import java.util.Arrays;
public class Solution {
    public int checkRecord(int n) {
        long MOD = 1000000007;
        long[][] dp = new long[n + 1][3];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            // Present
            dp[i][0] = (dp[i - 1][0] + dp[i - 1][1] + dp[i - 1][2]) % MOD;

            // Late
            dp[i][1] = (dp[i - 1][0] + dp[i - 1][1]) % MOD;

            // Absent
            dp[i][2] = dp[i - 1][0];
        }

        long total = (dp[n][0] + dp[n][1] + dp[n][2]) % MOD;

        long invalid = 0;
        // Count invalid records with 2 or more absences
        long[][] dpAbsence = new long[n + 1][2];
        dpAbsence[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            dpAbsence[i][0] = (dpAbsence[i - 1][0] + dpAbsence[i - 1][1]) % MOD;
            if (i >= 2) {
                dpAbsence[i][1] = (dpAbsence[i - 1][0] + dpAbsence[i - 1][1]) % MOD;
            } else {
                dpAbsence[i][1] = dpAbsence[i - 1][0];
            }
        }
        invalid = (invalid + dpAbsence[n][1]) % MOD;

        // Count invalid records with 3 or more consecutive late days
        long[][] dpLate = new long[n + 1][4];
        dpLate[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            dpLate[i][0] = (dpLate[i - 1][0] + dpLate[i - 1][1] + dpLate[i - 1][2] + dpLate[i - 1][3]) % MOD;
            dpLate[i][1] = dpLate[i - 1][0];
            dpLate[i][2] = dpLate[i - 1][1];
            dpLate[i][3] = dpLate[i - 1][2];
            if (i >= 3) {
                dpLate[i][3] = (dpLate[i][3] + dpLate[i - 1][3]) % MOD;
            }
        }
        invalid = (invalid + dpLate[n][3]) % MOD;

        long result = (total - invalid + MOD) % MOD;
        return (int) result;
    }
}

