import java.util.Arrays;

// #Hard #Array #Dynamic_Programming #Math #Tree #Binary_Tree #Union_Find #Binary_Search_Tree
// #Divide_and_Conquer #Memoization #Combinatorics
// #2022_04_11_Time_21_ms_(97.44%)_Space_49.9_MB_(92.31%)
public class Solution {
    private static final int MOD = 1000000007;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        if (n <= 2) {
            return 1;
        }

        long[][] dp = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], -1);
        }

        return (int) solve(nums, 0, n - 1, dp);
    }

    private long solve(int[] nums, int left, int right, long[][] dp) {
        if (left >= right) {
            return 1;
        }

        if (dp[left][right] != -1) {
            return dp[left][right];
        }

        long ans = 0;
        int root = nums[left];
        int rootIndex = -1;
        for (int i = left + 1; i <= right; i++) {
            if (nums[i] < root) {
                continue;
            }
            if (rootIndex == -1 || nums[i] < nums[rootIndex]) {
                rootIndex = i;
            }
        }

        if (rootIndex == -1) {
            rootIndex = right;
        }

        long leftWays = 1;
        for (int i = left + 1; i < rootIndex; i++) {
            if (nums[i] < root) {
                leftWays = (leftWays * combinations(rootIndex - i - 1, rootIndex - i - 1)) % MOD;
            }
        }

        long rightWays = 1;
        for (int i = rootIndex + 1; i <= right; i++) {
            if (nums[i] > root) {
                rightWays = (rightWays * combinations(i - rootIndex - 1, i - rootIndex - 1)) % MOD;
            }
        }

        long leftCount = 0;
        for (int i = left + 1; i < rootIndex; i++) {
            if (nums[i] < root) {
                leftCount++;
            }
        }

        long rightCount = 0;
        for (int i = rootIndex + 1; i <= right; i++) {
            if (nums[i] > root) {
                rightCount++;
            }
        }

        long leftSubtreeWays = solve(nums, left + 1, rootIndex - 1, dp);
        long rightSubtreeWays = solve(nums, rootIndex + 1, right, dp);

        long result = (leftSubtreeWays * rightSubtreeWays) % MOD;

        if (leftCount == 0 && rightCount == 0) {
            result = 1;
        }

        dp[left][right] = result;
        return result;
    }

    private long combinations(int n, int k) {
        if (k < 0 || k > n) {
            return 0;
        }
        if (k == 0 || k == n) {
            return 1;
        }
        if (k > n / 2) {
            k = n - k;
        }
        long result = 1;
        for (int i = 1; i <= k; ++i) {
            result = (result * (n - i + 1)) % MOD;
            result = (result * modInverse(i, MOD)) % MOD;
        }
        return result;
    }

    private long modInverse(long a, long m) {
        long m0 = m;
        long y = 0, x = 1;

        if (m == 1)
            return 0;

        while (a > 1) {
            long q = a / m;
            long t = m;

            m = a % m;
            a = t;
            t = y;

            y = x - q * y;
            x = t;
        }

        if (x < 0)
            x += m0;

        return x;
    }
}

