public class Solution {
    public int unhappyFriends(int n, int[][] preferences, int[][] pairs) {
        Map<Integer, Integer> partner = new HashMap<>();
        for (int[] pair : pairs) {
            partner.put(pair[0], pair[1]);
            partner.put(pair[1], pair[0]);
        }

        int unhappyCount = 0;
