import java.util.HashMap;
public class Solution {
    public int minSubarray(int[] nums, int p) {
        int n = nums.length;
        long prefixSum = 0;
        HashMap<Long, Integer> map = new HashMap<>();
        map.put(0L, -1);
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            prefixSum = (prefixSum + nums[i]) % p;
            if (map.containsKey(prefixSum)) {
                minLen = Math.min(minLen, i - map.get(prefixSum));
            } else {
                map.put(prefixSum, i);
            }
        }
        if (minLen == Integer.MAX_VALUE) {
            return -1;
        }
        long totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }
        if (totalSum % p == 0) {
            return 0;
        }
        if (minLen == n) {
            return -1;
        }
        return minLen;
    }
}

