public class Solution {
    public int minOperationsMaxProfit(int[] customers, int boardingCost, int runningCost) {
        int waiting = 0;
        int boarded = 0;
        int profit = 0;
        int maxProfit = 0;
        int operations = 0;
        int i = 0;

        while (i < customers.length || waiting > 0) {
            operations++;
            if (i < customers.length) {
                waiting += customers[i];
            }

            int boardedThisRound = Math.min(4, waiting);
            waiting -= boardedThisRound;
            boarded += boardedThisRound;
            profit += boardedThisRound * boardingCost - runningCost;

            if (profit > maxProfit) {
                maxProfit = profit;
            }

            if (i == customers.length && waiting == 0) {
                break;
            }
            i++;
        }

        if (maxProfit <= 0) {
            return -1;
        }

        return operations;
    }
}

