import java.util.Arrays;
import java.util.List;

public class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
        int size1 = cost.size();
        int size2 = cost.get(0).size();
        int[] dp = new int[1 << size2];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 0; i < size1; i++) {
            int[] nextDp = new int[1 << size2];
            Arrays.fill(nextDp, Integer.MAX_VALUE);

            for (int mask = 0; mask < (1 << size2); mask++) {
                if (dp[mask] != Integer.MAX_VALUE) {
                    for (int j = 0; j < size2; j++) {
                        int newMask = mask | (1 << j);
                        nextDp[newMask] = Math.min(nextDp[newMask], dp[mask] + cost.get(i).get(j));
                    }
                }
            }
            dp = nextDp;
        }

        int minCost = Integer.MAX_VALUE;
        for (int mask = (1 << size2) - 1; mask >= 0; mask--) {
            minCost = Math.min(minCost, dp[mask]);
        }

        return minCost;
    }
}

