public class Solution {
    public int minSwaps(int[][] grid) {
        int n = grid.length;
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (grid[i][j] == 1) {
                    int k = j;
                    while (k > i && grid[k][j] == 1) {
                        k--;
                    }
                    if (k != j) {
                        for (int l = j; l > k; l--) {
                            int[] temp = grid[l];
                            grid[l] = grid[l - 1];
                            grid[l - 1] = temp;
                            swaps++;
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (grid[i][j] == 1) {
                    return -1;
                }
            }
        }

        return swaps;
    }
}

