// #Easy #String #2022_04_11_Time_3_ms_(67.74%)_Space_40.3_MB_(93.33%)
public class Solution {
    public String reorderSpaces(String text) {
        int spaces = 0;
        for (char c : text.toCharArray()) {
            if (c == ' ') {
                spaces++;
            }
        }

        String[] words = text.trim().split("\\s+");
        int wordCount = words.length;

        if (wordCount == 1) {
            return words[0] + " ".repeat(spaces);
        }

        int spacesBetween = spaces / (wordCount - 1);
        int extraSpaces = spaces % (wordCount - 1);

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < wordCount - 1; i++) {
            result.append(words[i]);
            result.append(" ".repeat(spacesBetween));
        }
        result.append(words[wordCount - 1]);
        result.append(" ".repeat(extraSpaces));

        while (result.length() < text.length()) {
            result.append(" ");
        }

        return result.toString();
    }
}

