// #2022_04_09_Time_3_ms_(94.18%)_Space_52.2_MB_(60.26%)
import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int countPairs(TreeNode root, int distance) {
        List<TreeNode> leaves = new ArrayList<>();
        findLeaves(root, leaves);

        int count = 0;
        for (int i = 0; i < leaves.size(); i++) {
            for (int j = i + 1; j < leaves.size(); j++) {
                if (shortestPath(leaves.get(i), leaves.get(j), root) <= distance) {
                    count++;
                }
            }
        }

        return count;
    }

    private void findLeaves(TreeNode node, List<TreeNode> leaves) {
        if (node == null) {
            return;
        }

        if (node.left == null && node.right == null) {
            leaves.add(node);
            return;
        }

        findLeaves(node.left, leaves);
        findLeaves(node.right, leaves);
    }

    private int shortestPath(TreeNode node1, TreeNode node2, TreeNode root) {
        List<TreeNode> path1 = new ArrayList<>();
        List<TreeNode> path2 = new ArrayList<>();

        findPath(root, node1, path1);
        findPath(root, node2, path2);

        int i = 0;
        while (i < path1.size() && i < path2.size() && path1.get(i).equals(path2.get(i))) {
            i++;
        }

        return path1.size() - i + path2.size() - i;
    }

    private boolean findPath(TreeNode node, TreeNode target, List<TreeNode> path) {
        if (node == null) {
            return false;
        }

        path.add(node);

        if (node.equals(target)) {
            return true;
        }

        if (findPath(node.left, target, path) || findPath(node.right, target, path)) {
            return true;
        }

        path.remove(path.size() - 1);
        return false;
    }
}

