import java.util.Arrays;
public class Solution {
    public String minInteger(String num, int k) {
        char[] arr = num.toCharArray();
        int n = arr.length;
        for (int i = 0; i < n && k > 0; i++) {
            int minIndex = i;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] < arr[minIndex]) {
                    minIndex = j;
                }
            }
            if (minIndex != i) {
                int swaps = minIndex - i;
                if (swaps <= k) {
                    for (int j = minIndex; j > i; j--) {
                        char temp = arr[j];
                        arr[j] = arr[j - 1];
                        arr[j - 1] = temp;
                    }
                    k -= swaps;
                } else {
                    for (int j = minIndex; j > i && k > 0; j--) {
                        char temp = arr[j];
                        arr[j] = arr[j - 1];
                        arr[j - 1] = temp;
                        k--;
                    }
                }
            }
        }
        return new String(arr);
    }
}

