import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minDays(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        if (m == 1 && n == 1) {
            return 0;
        }

        if (countIslands(grid) == 0) {
            return 0;
        }

        if (countIslands(grid) > 1) {
            return 0;
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int[][] tempGrid = new int[m][n];
                    for (int r = 0; r < m; r++) {
                        for (int c = 0; c < n; c++) {
                            tempGrid[r][c] = grid[r][c];
                        }
                    }
                    tempGrid[i][j] = 0;
                    if (countIslands(tempGrid) > 1) {
                        return 1;
                    }
                }
            }
        }

        return 2;
    }

    private int countIslands(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    dfs(grid, i, j, visited);
                    count++;
                }
            }
        }

        return count;
    }

    private void dfs(int[][] grid, int row, int col, boolean[][] visited) {
        int m = grid.length;
        int n = grid[0].length;

        if (row < 0 || row >= m || col < 0 || col >= n || grid[row][col] == 0 || visited[row][col]) {
            return;
        }

        visited[row][col] = true;

        dfs(grid, row + 1, col, visited);
        dfs(grid, row - 1, col, visited);
        dfs(grid, row, col + 1, visited);
        dfs(grid, row, col - 1, visited);
    }
}

