import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.PriorityQueue;
import java.util.Comparator;

public class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<Pair>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            adj.get(u).add(new Pair(v, succProb[i]));
            adj.get(v).add(new Pair(u, succProb[i]));
        }

        double[] probabilities = new double[n];
        probabilities[start] = 1.0;

        PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingDouble(p -> -p.probability));
        pq.offer(new Pair(start, 1.0));

        while (!pq.isEmpty()) {
            Pair current = pq.poll();
            int node = current.node;
            double probability = current.probability;

            if (probability < probabilities[node]) {
                continue;
            }

            for (Pair neighbor : adj.get(node)) {
                int nextNode = neighbor.node;
                double nextProbability = probability * neighbor.probability;

                if (nextProbability > probabilities[nextNode]) {
                    probabilities[nextNode] = nextProbability;
                    pq.offer(new Pair(nextNode, nextProbability));
                }
            }
        }

        return probabilities[end];
    }

    static class Pair {
        int node;
        double probability;

        public Pair(int node, double probability) {
            this.node = node;
            this.probability = probability;
        }
    }
}

