public class Solution {
    public int minCost(String s, int[] cost) {
        int n = s.length();
        int totalCost = 0;
        int i = 0;
        while (i < n - 1) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                int j = i + 1;
                int maxCost = 0;
                int sumCost = 0;
                while (j < n && s.charAt(i) == s.charAt(j)) {
                    sumCost += cost[j];
                    maxCost = Math.max(maxCost, cost[j]);
                    j++;
                }
                totalCost += sumCost - maxCost;
                i = j;
            } else {
                i++;
            }
        }
        return totalCost;
    }
}

