import java.util.Arrays;
public class Solution {
    public int rangeSum(int[] nums, int n, int left, int right) {
        int[] sums = new int[n * (n + 1) / 2];
        int k = 0;
        for (int i = 0; i < n; i++) {
            int currentSum = 0;
            for (int j = i; j < n; j++) {
                currentSum += nums[j];
                sums[k++] = currentSum;
            }
        }
        Arrays.sort(sums);
        long sum = 0;
        for (int i = left - 1; i < right; i++) {
            sum = (sum + sums[i]) % 1000000007;
        }
        return (int) sum;
    }
}

