public class Solution {
    public int getMaxLen(int[] nums) {
        int positive = 0;
        int negative = 0;
        int maxLen = 0;

        for (int num : nums) {
            if (num > 0) {
                positive++;
                negative = (negative == 0) ? 0 : negative + 1;
            } else if (num < 0) {
                int temp = positive;
                positive = (negative == 0) ? 0 : negative + 1;
                negative = temp + 1;
            } else {
                positive = 0;
                negative = 0;
            }

            maxLen = Math.max(maxLen, positive);
        }

        return maxLen;
    }
}

