import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] countSubTrees(int n, int[][] edges, String labelsString) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int[] ans = new int[n];
        boolean[] visited = new boolean[n];
        dfs(0, adj, labelsString, ans, visited);
        return ans;
    }

    private int dfs(int node, List<List<Integer>> adj, String labelsString, int[] ans, boolean[] visited) {
        visited[node] = true;
        int count = 1;
        char label = labelsString.charAt(node);

        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                count += dfs(neighbor, adj, labelsString, ans, visited);
            }
        }

        ans[node] = 0;
        for (int i = 0; i < ans.length; i++) {
            if (labelsString.charAt(i) == label) {
                ans[node]++;
            }
        }

        return count;
    }
}

