// #Medium #String #Hash_Table #Backtracking #2022_04_06_Time_8_ms_(95.81%)_Space_42.6_MB_(84.70%)
import java.util.HashSet;
import java.util.Set;
public class Solution {
    public int maxUniqueSplit(String s) {
        return maxUniqueSplitHelper(s, 0, new HashSet<>());
    }

    private int maxUniqueSplitHelper(String s, int start, Set<String> seen) {
        if (start == s.length()) {
            return 0;
        }

        int maxCount = 0;
        for (int i = start; i < s.length(); i++) {
            String sub = s.substring(start, i + 1);
            if (!seen.contains(sub)) {
                seen.add(sub);
                int count = 1 + maxUniqueSplitHelper(s, i + 1, seen);
                maxCount = Math.max(maxCount, count);
                seen.remove(sub); // Backtrack
            }
        }
        return maxCount;
    }
}

