// #Medium #Array #Dynamic_Programming #Matrix
// #2022_04_06_Time_1_ms_(100.00%)_Space_41.7_MB_(89.38%)
public class Solution {

    static class Tuple {
        long max;
        long min;

        public Tuple(long a, long b) {
            this.max = a;
            this.min = b;
        }
    }

    public long maxNonNegativeProduct(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        Tuple[][] dp = new Tuple[m][n];

        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i], null);
        }

        if (grid[0][0] >= 0) {
            dp[0][0] = new Tuple(grid[0][0], grid[0][0]);
        } else {
            dp[0][0] = new Tuple(0, grid[0][0]);
        }

        for (int i = 1; i < m; i++) {
            if (grid[i][0] >= 0) {
                dp[i][0] = new Tuple(dp[i - 1][0].max * grid[i][0], dp[i - 1][0].min * grid[i][0]);
            } else {
                dp[i][0] = new Tuple(Math.max(dp[i - 1][0].max * grid[i][0], 0), Math.min(dp[i - 1][0].min * grid[i][0], 0));
            }
        }

        for (int j = 1; j < n; j++) {
            if (grid[0][j] >= 0) {
                dp[0][j] = new Tuple(dp[0][j - 1].max * grid[0][j], dp[0][j - 1].min * grid[0][j]);
            } else {
                dp[0][j] = new Tuple(Math.max(dp[0][j - 1].max * grid[0][j], 0), Math.min(dp[0][j - 1].min * grid[0][j], 0));
            }
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                long max1 = dp[i - 1][j].max * grid[i][j];
                long min1 = dp[i - 1][j].min * grid[i][j];
                long max2 = dp[i][j - 1].max * grid[i][j];
                long min2 = dp[i][j - 1].min * grid[i][j];

                long maxVal = Math.max(Math.max(max1, max2), 0);
                long minVal = Math.min(Math.min(min1, min2), 0);

                dp[i][j] = new Tuple(maxVal, minVal);
            }
        }

        long result = dp[m - 1][n - 1].max;
        if (result < 0) {
            return -1;
        }
        return result % 1000000007;
    }
}

