// #Medium #String #Math #2022_04_11_Time_9_ms_(82.09%)_Space_42.7_MB_(87.31%)
public class Solution {
    public int numWays(String s) {
        int n = s.length();
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') {
                ones++;
            }
        }

        if (ones % 3 != 0) {
            return 0;
        }

        if (ones == 0) {
            long result = 1;
            for (int i = 0; i < n - 1; i++) {
                result = (result * (n - 1 - i)) % 1000000007;
                long inv = power(i + 1, 1000000007 - 2, 1000000007);
                result = (result * inv) % 1000000007;
            }
            return (int) result;
        }

        int target = ones / 3;
        int count1 = 0;
        int count2 = 0;
        long result = 0;

        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                count1++;
            }
            if (count1 == target) {
                for (int j = i + 1; j < n; j++) {
                    if (s.charAt(j) == '1') {
                        count2++;
                    }
                    if (count2 == target) {
                        result = (result + 1) % 1000000007;
                    }
                }
            }
        }

        return (int) result;
    }

    private long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
}

