public class Solution {
    public int getLastMoment(int n, int[] left, int[] right) {
        int maxLeft = 0;
        for (int pos : left) {
            maxLeft = Math.max(maxLeft, pos);
        }

        int minRight = n;
        for (int pos : right) {
            minRight = Math.min(minRight, pos);
        }

        int time = 0;
        if (maxLeft > minRight) {
            time = Math.max(maxLeft, n - minRight);
        } else {
            time = Math.max(maxLeft, n - minRight);
        }

        int maxTime = 0;
        for(int pos : left){
            maxTime = Math.max(maxTime, pos);
        }
        for(int pos : right){
            maxTime = Math.max(maxTime, n - pos);
        }

        return maxTime;
    }
}

