// #Hard #String #Dynamic_Programming #2022_04_09_Time_34_ms_(83.91%)_Space_54.2_MB_(25.65%)
public class Solution {
    public int compress(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];

        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }

        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                // Option 1: Delete the current character
                if (j > 0) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j - 1]);
                }

                // Option 2: Keep the current character
                int count = 1;
                int l = i - 1;
                while (l >= 0 && s.charAt(l) == s.charAt(i - 1)) {
                    count++;
                    l--;
                }

                int cost = (count == 1) ? 1 : (int) (Math.log10(count) + 1);
                if (cost <= k) {
                    dp[i][k] = Math.min(dp[i][k], dp[l + 1][k - cost] + 1);
                }
            }
        }

        int minLength = Integer.MAX_VALUE;
        for (int j = 0; j <= k; j++) {
            minLength = Math.min(minLength, dp[n][j]);
        }

        return minLength;
    }
}

