// #2022_04_11_Time_22_ms_(82.51%)_Space_135.8_MB_(70.24%)
public class Solution {
    public boolean containsCycle(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j]) {
                    if (dfs(grid, i, j, -1, -1, grid[i][j], visited)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean dfs(char[][] grid, int row, int col, int parentRow, int parentCol, char target, boolean[][] visited) {
        if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != target) {
            return false;
        }

        if (visited[row][col]) {
            return true;
        }

        visited[row][col] = true;

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (newRow == parentRow && newCol == parentCol) {
                continue;
            }

            if (dfs(grid, newRow, newCol, row, col, target, visited)) {
                return true;
            }
        }

        return false;
    }
}

