import java.util.Arrays;
public class Solution {
    public int longestAwesome(String s) {
        int[] mask = new int[1 << 16];
        Arrays.fill(mask, -1);
        mask[0] = 0;
        int ans = 0;
        int cur = 0;
        for (int i = 0; i < s.length(); i++) {
            cur ^= (1 << (s.charAt(i) - 'a'));
            if (mask[cur] == -1) {
                mask[cur] = i + 1;
            } else {
                ans = Math.max(ans, i + 1 - mask[cur]);
            }
            for (int j = 0; j < 16; j++) {
                int temp = cur ^ (1 << j);
                if (mask[temp] != -1) {
                    ans = Math.max(ans, i + 1 - mask[temp]);
                }
            }
        }
        return ans;
    }
}

