// #Hard #Array #Dynamic_Programming #Memoization
// #2022_04_11_Time_111_ms_(72.26%)_Space_44.6_MB_(64.16%)
public class Solution {
    private static final int MOD = 1000000007;

    public int countRoutes(int[] locations, int start, int finish, int fuel) {
        int n = locations.length;
        Integer[][][] dp = new Integer[n][fuel + 1][n];
        return solve(locations, start, finish, fuel, dp);
    }

    private int solve(int[] locations, int currentCity, int finishCity, int remainingFuel, Integer[][][] dp) {
        if (remainingFuel < 0) {
            return 0;
        }

        if (currentCity == finishCity) {
            return 1;
        }

        if (dp[currentCity][remainingFuel][finishCity] != null) {
            return dp[currentCity][remainingFuel][finishCity];
        }

        long count = 0;
        for (int nextCity = 0; nextCity < locations.length; nextCity++) {
            if (nextCity != currentCity) {
                int cost = Math.abs(locations[currentCity] - locations[nextCity]);
                count = (count + solve(locations, nextCity, finishCity, remainingFuel - cost, dp)) % MOD;
            }
        }

        dp[currentCity][remainingFuel][finishCity] = (int) count;
        return (int) count;
    }
}

