// #Medium #Array #Binary_Search #Simulation #Binary_Search_II_Day_19
// #2022_04_11_Time_8_ms_(90.00%)_Space_84.2_MB_(53.00%)
public class Solution {
    public int findLatestStep(int[] arr, int m) {
        int n = arr.length;
        int[] bit = new int[n + 1];
        int latestStep = -1;

        for (int i = 0; i < n; i++) {
            int index = arr[i] - 1;
            update(bit, index + 1, 1);

            int start = Math.max(0, index - m + 1);
            int end = index;

            int count = query(bit, end) - query(bit, start);

            if (count == m) {
                latestStep = i + 1;
            }
        }

        return latestStep;
    }

    private void update(int[] bit, int index, int value) {
        while (index < bit.length) {
            bit[index] += value;
            index += index & -index;
        }
    }

    private int query(int[] bit, int index) {
        int sum = 0;
        while (index > 0) {
            sum += bit[index];
            index -= index & -index;
        }
        return sum;
    }
}

