public class Solution {
    public int maxSumRangeQuery(int[] nums, int[][] requests) {
        int n = nums.length;
        int mod = 1000000007;
        int[] diff = new int[n];
        for (int[] request : requests) {
            int start = request[0];
            int end = request[1];
            diff[start]++;
            if (end + 1 < n) {
                diff[end + 1]--;
            }
        }
        int[] prefixSum = new int[n];
        prefixSum[0] = diff[0];
        for (int i = 1; i < n; i++) {
            prefixSum[i] = prefixSum[i - 1] + diff[i];
        }
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }
        Arrays.sort(indices, (a, b) -> Integer.compare(prefixSum[b], prefixSum[a]));
        long maxSum = 0;
        for (int i = 0; i < n; i++) {
            int index = indices[i];
            maxSum = (maxSum + (long) nums[index] * prefixSum[index]) % mod;
        }
        return (int) maxSum;
    }
}

