import java.util.Arrays;
public class Solution {
    public int maxNumEdgesToRemove(int n, int[][] edges) {
        int[] aliceParent = new int[n + 1];
        int[] bobParent = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            aliceParent[i] = i;
            bobParent[i] = i;
        }
        int removedEdges = 0;
        int aliceEdges = 0;
        int bobEdges = 0;
        for (int[] edge : edges) {
            int type = edge[0];
            int u = edge[1];
            int v = edge[2];
            if (type == 3) {
                if (find(aliceParent, u) != find(aliceParent, v)) {
                    union(aliceParent, u, v);
                    union(bobParent, u, v);
                    aliceEdges++;
                    bobEdges++;
                } else {
                    removedEdges++;
                }
            } else if (type == 1) {
                if (find(aliceParent, u) != find(aliceParent, v)) {
                    union(aliceParent, u, v);
                    aliceEdges++;
                } else {
                    removedEdges++;
                }
            } else {
                if (find(bobParent, u) != find(bobParent, v)) {
                    union(bobParent, u, v);
                    bobEdges++;
                } else {
                    removedEdges++;
                }
            }
        }
        int aliceComponents = 0;
        int bobComponents = 0;
        for (int i = 1; i <= n; i++) {
            if (aliceParent[i] == i) {
                aliceComponents++;
            }
            if (bobParent[i] == i) {
                bobComponents++;
            }
        }
        if (aliceComponents > 1 || bobComponents > 1) {
            return -1;
        }
        return removedEdges;
    }

    private int find(int[] parent, int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent, parent[i]);
    }

    private void union(int[] parent, int u, int v) {
        int rootU = find(parent, u);
        int rootV = find(parent, v);
        if (rootU != rootV) {
            parent[rootU] = rootV;
        }
    }
}

