                    for (int j = i + 1; j < indices.size() - 1; j++) {
                        for (int k = j + 1; k < indices.size(); k++) {
                            int len = indices.get(k) - indices.get(i) + 1;
                            boolean isSpecial = true;
                            for (int l = indices.get(i); l <= indices.get(k); l++) {
                                if (s.charAt(l) != c) {
                                    isSpecial = false;
                                    break;
                                }
                            }
                            if (isSpecial) {
                                maxLength = Math.max(maxLength, len);
                            }
                        }
                    }
                }
            }
        }

        return maxLength;
    }
}

