import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minCost(String source, String target, char[] original, char[] changed, int[] cost) {
        int n = source.length();
        Map<Character, Map<Character, Integer>> charMap = new HashMap<>();
        for (int i = 0; i < original.length; i++) {
            char o = original[i];
            char c = changed[i];
            int co = cost[i];
            charMap.computeIfAbsent(o, k -> new HashMap<>()).put(c, co);
        }

        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = (source.charAt(0) == target.charAt(0)) ? 0 : getCost(source.charAt(0), target.charAt(0), charMap);

        for (int i = 1; i < n; i++) {
            if (source.charAt(i) == target.charAt(i)) {
                dp[i] = dp[i - 1];
            } else {
                int costToChange = getCost(source.charAt(i), target.charAt(i), charMap);
                if (costToChange != -1 && dp[i - 1] != Integer.MAX_VALUE) {
                    dp[i] = Math.min(dp[i], dp[i - 1] + costToChange);
                }
            }
        }

        return dp[n - 1] == Integer.MAX_VALUE ? -1 : dp[n - 1];
    }

    private int getCost(char sourceChar, char targetChar, Map<Character, Map<Character, Integer>> charMap) {
        if (sourceChar == targetChar) {
            return 0;
        }
        if (charMap.containsKey(sourceChar) && charMap.get(sourceChar).containsKey(targetChar)) {
            return charMap.get(sourceChar).get(targetChar);
        }
        return -1;
    }
}

