public class Solution {
    public int minimumAddedCoins(int[] coins, int target) {
        Arrays.sort(coins);
        int addedCoins = 0;
        int reachable = 0;
        for (int coin : coins) {
            if (coin > reachable + 1) {
                int diff = coin - (reachable + 1);
                addedCoins += diff;
                reachable += diff;
            }
            reachable += coin;
            if (reachable >= target) {
                break;
            }
        }
        if (reachable < target) {
            addedCoins += (target - reachable);
        }
        return addedCoins;
    }
