import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int countWaysToMakeConnected(int n, int maxDistance, int[][] roads) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] road : roads) {
            int u = road[0];
            int v = road[1];
            int w = road[2];
            adj.get(u).add(new int[]{v, w});
            adj.get(v).add(new int[]{u, w});
        }

        int count = 0;
        for (int i = 0; i < (1 << n); i++) {
            List<Integer> remainingBranches = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    remainingBranches.add(j);
                }
            }

            if (remainingBranches.isEmpty()) {
                continue;
            }

            boolean valid = true;
            for (int startNode : remainingBranches) {
                for (int endNode : remainingBranches) {
                    if (startNode == endNode) {
                        continue;
                    }
                    int distance = dijkstra(n, adj, startNode, endNode);
                    if (distance > maxDistance) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) {
                    break;
                }
            }

            if (valid) {
                count++;
            }
        }

        return count;
    }

    private int dijkstra(int n, List<List<int[]>> adj, int startNode, int endNode) {
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[startNode] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{0, startNode});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0];
            int u = curr[1];

            if (d > dist[u]) {
                continue;
            }

            for (int[] edge : adj.get(u)) {
                int v = edge[0];
                int w = edge[1];
                if (dist[v] > dist[u] + w) {
                    dist[v] = dist[u] + w;
                    pq.offer(new int[]{dist[v], v});
                }
            }
        }

        return dist[endNode];
    }
}

