// #Hard #Array #Sorting #Greedy #Matrix #Heap_Priority_Queue
// #2024_01_02_Time_18_ms_(79.00%)_Space_55.4_MB_(78.52%)
public class Solution {

    static class Node {
        int row;
        int col;
        int val;

        public Node(int row, int col, int val) {
            this.row = row;
            this.col = col;
            this.val = val;
        }
    }

    public long maxSpending(int[][] values) {
        int m = values.length;
        int n = values[0].length;
        boolean[][] bought = new boolean[m][n];
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> b.val - a.val);

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                pq.offer(new Node(i, j, values[i][j]));
            }
        }

        long totalSpending = 0;
        for (int day = 1; day <= m * n; day++) {
            Node top = pq.poll();
            int row = top.row;
            int col = top.col;

            if (!bought[row][col]) {
                bought[row][col] = true;
                totalSpending += (long) values[row][col] * day;
            } else {
                // Find the next available item
                while (!pq.isEmpty()) {
                    top = pq.poll();
                    row = top.row;
                    col = top.col;
                    if (!bought[row][col]) {
                        bought[row][col] = true;
                        totalSpending += (long) values[row][col] * day;
                        break;
                    }
                }
                if (pq.isEmpty()) {
                    break;
                }
            }
        }

        return totalSpending;
    }
}

