public class Solution {
    public int minimumChanges(String s, int k) {
        int n = s.length();
        if (k == 1) {
            return changesToPalindrome(s);
        }

        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = Integer.MAX_VALUE;
            }
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int l = 1; l <= i; l++) {
                    String sub = s.substring(i - l, i);
                    int changes = changesToPalindrome(sub);
                    if (dp[i - l][j - 1] != Integer.MAX_VALUE) {
                        dp[i][j] = Math.min(dp[i][j], dp[i - l][j - 1] + changes);
                    }
                }
            }
        }

        return dp[n][k];
    }

    private int changesToPalindrome(String s) {
        int n = s.length();
        int changes = 0;
        for (int i = 0; i < n / 2; i++) {
            if (s.charAt(i) != s.charAt(n - 1 - i)) {
                changes++;
            }
        }
        return changes;
    }
}

