public class Solution {
    public boolean areSimilar(int[][] mat, int k) {
        int m = mat.length;
        int n = mat[0].length;

        int[][] shiftedMat = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                shiftedMat[i][j] = mat[i][j];
            }
        }

        for (int i = 0; i < m; i++) {
            if (i % 2 == 0) {
                // Even indexed row: cyclically left shift k times
                int[] row = shiftedMat[i];
                int[] newRow = new int[n];
                for (int j = 0; j < n; j++) {
                    newRow[(j - k + n) % n] = row[j];
                }
                shiftedMat[i] = newRow;
            } else {
                // Odd indexed row: cyclically right shift k times
                int[] row = shiftedMat[i];
                int[] newRow = new int[n];
                for (int j = 0; j < n; j++) {
                    newRow[(j + k) % n] = row[j];
                }
                shiftedMat[i] = newRow;
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] != shiftedMat[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }
}

