public class Solution {
    public int missingInteger(int[] nums) {
        int n = nums.length;
        int maxSequentialSum = 0;
        int currentSum = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                currentSum = nums[i];
            } else {
                if (nums[i] == nums[i - 1] + 1) {
                    currentSum = nums[i];
                } else {
                    break;
                }
            }
            maxSequentialSum = Math.max(maxSequentialSum, currentSum);
        }

        if (n == 0) {
            return 1;
        }

        int missing = 1;
        Arrays.sort(nums);
        for (int num : nums) {
            if (num == missing) {
                missing++;
            } else if (num > missing) {
                break;
            }
        }

        if (missing <= maxSequentialSum) {
            while (Arrays.binarySearch(nums, missing) >= 0) {
                missing++;
            }
        }

        return missing;
    }
}

