                if (dp[i][j] == Integer.MAX_VALUE) continue;

                // Option 1: No operation
                if (i < n && source.charAt(i) == target.charAt(i)) {
                    dp[i + 1][j] = Math.min(dp[i + 1][j], dp[i][j]);
                }

