    private boolean canMakePalindrome(String s, int a, int b, int c, int d) {
        int n = s.length();
        char[] firstHalf = s.substring(0, n / 2).toCharArray();
        char[] secondHalf = s.substring(n / 2).toCharArray();
        Map<Character, Integer> firstHalfCounts = new HashMap<>();
        Map<Character, Integer> secondHalfCounts = new HashMap<>();
        for (char c : firstHalf) {
            firstHalfCounts.put(c, firstHalfCounts.getOrDefault(c, 0) + 1);
        }
        for (char c : secondHalf) {
            secondHalfCounts.put(c, secondHalfCounts.getOrDefault(c, 0) + 1);
        }
        int diffCount = 0;
        for (Map.Entry<Character, Integer> entry : firstHalfCounts.entrySet()) {
            char c = entry.getKey();
            int count1 = entry.getValue();
            int count2 = secondHalfCounts.getOrDefault(c, 0);
            if (count1 != count2) {
                diffCount++;
            }
        }
        for (Map.Entry<Character, Integer> entry : secondHalfCounts.entrySet()) {
            char c = entry.getKey();
            if (!firstHalfCounts.containsKey(c)) {
                diffCount++;
            }
        }
        if (diffCount > 0) {
            return false;
        }
        int firstDiff = -1;
        int secondDiff = -1;
        for (int i = 0; i < n / 2; i++) {
            if (firstHalf[i] != secondHalf[n / 2 + i]) {
                firstDiff = i;
                break;
            }
        }
        if (firstDiff == -1) {
            return true;
        }
        boolean canSolveWithFirstInterval = false;
        if (a <= firstDiff && b >= firstDiff) {
            canSolveWithFirstInterval = true;
        }
        boolean canSolveWithSecondInterval = false;
        if (c <= firstDiff + n / 2 && d >= firstDiff + n / 2) {
            canSolveWithSecondInterval = true;
        }
        return canSolveWithFirstInterval || canSolveWithSecondInterval;
    }
