public class Solution {
    public int minimumCoins(int[] prices) {
        int n = prices.length;
        int[] dp = new int[n + 1];
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1] + prices[i - 1];
            for (int j = 1; j <= i; j++) {
                int cost = prices[i - 1];
                int prev = i - j;
