// #Medium #Array #Matrix #Prefix_Sum #2023_12_26_Time_11_ms_(84.62%)_Space_73.2_MB_(28.57%)
public class Solution {
    public int[][] constructProductMatrix(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] productMatrix = new int[n][m];
        int totalProduct = 1;
        int zeroCount = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != 0) {
                    totalProduct = (totalProduct * grid[i][j]) % 1000000007;
                } else {
                    zeroCount++;
                }
            }
        }

        if (zeroCount > 1) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    productMatrix[i][j] = 0;
                }
            }
            return productMatrix;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) {
                    int product = 1;
                    for (int row = 0; row < n; row++) {
                        for (int col = 0; col < m; col++) {
                            if (row != i || col != j) {
                                product = (product * grid[row][col]) % 1000000007;
                            }
                        }
                    }
                    productMatrix[i][j] = product;
                } else {
                    productMatrix[i][j] = (totalProduct * power(grid[i][j], 1000000007 - 2, 1000000007)) % 1000000007;
                }
            }
        }

        return productMatrix;
    }

    private int power(int base, int exp, int mod) {
        int res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
}

