// #Medium #Dynamic_Programming #Breadth_First_Search #Memoization
// #2024_01_17_Time_0_ms_(100.00%)_Space_41.2_MB_(92.39%)
public class Solution {
    public int minimumOperationsToMakeEqual(int x, int y) {
        if (x == y) {
            return 0;
        }

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{x, 0});

        Set<Integer> visited = new HashSet<>();
        visited.add(x);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int val = current[0];
            int steps = current[1];

            if (val == y) {
                return steps;
            }

            // Divide by 11
            if (val % 11 == 0) {
                int nextVal = val / 11;
                if (!visited.contains(nextVal)) {
                    queue.offer(new int[]{nextVal, steps + 1});
                    visited.add(nextVal);
                }
            }

            // Divide by 5
            if (val % 5 == 0) {
                int nextVal = val / 5;
                if (!visited.contains(nextVal)) {
                    queue.offer(new int[]{nextVal, steps + 1});
                    visited.add(nextVal);
                }
            }

            // Increment
            int nextValIncrement = val + 1;
            if (nextValIncrement <= 10000 && !visited.contains(nextValIncrement)) {
                queue.offer(new int[]{nextValIncrement, steps + 1});
                visited.add(nextValIncrement);
            }

            // Decrement
            int nextValDecrement = val - 1;
            if (nextValDecrement >= 1 && !visited.contains(nextValDecrement)) {
                queue.offer(new int[]{nextValDecrement, steps + 1});
                visited.add(nextValDecrement);
            }
        }

        return -1;
    }
}

