import java.util.ArrayList;
import java.util.List;

public class Solution {
    private int maxPoints = 0;

    public int collectCoins(int[] coins, int k, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < coins.length; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        dfs(0, -1, coins, k, adj);
        return maxPoints;
    }

    private long dfs(int node, int parent, int[] coins, int k, List<List<Integer>> adj) {
        long currentPoints = 0;
        long option1 = (long) (coins[node] - k);
        if (option1 < 0) {
            option1 = (long) -option1;
        }
        long option2 = (long) (coins[node] / 2);

        if (option1 > option2) {
            currentPoints = option1;
            for (int child : adj.get(node)) {
                if (child != parent) {
                    currentPoints += dfs(child, node, coins, k, adj);
                }
            }
        } else {
            currentPoints = option2;
            for (int child : adj.get(node)) {
                if (child != parent) {
                    int originalCoins = coins[child];
                    coins[child] /= 2;
                    currentPoints += dfs(child, node, coins, k, adj);
                    coins[child] = originalCoins;
                }
            }
        }
        maxPoints = (int) Math.max((long) maxPoints, currentPoints);
        return currentPoints;
    }
}

