        for (int num : nums) {
            pq.offer(num);
        }
        int operations = 0;
        while (pq.size() >= 2) {
            int x = pq.poll();
            int y = pq.poll();
            if (x >= k && y >= k) {
                pq.offer(x);
                pq.offer(y);
                break;
            }
            int newElement = Math.min(x, y) * 2 + Math.max(x, y);
            pq.offer(newElement);
            operations++;
        }
        int count = 0;
        while (!pq.isEmpty()) {
            if (pq.poll() >= k) {
                count++;
            }
        }
        return operations;
    }
}

