public class Solution {
    public long[] unmarkedSumArray(int[] nums, int[][] queries) {
        int n = nums.length;
        int m = queries.length;
        long[] answer = new long[m];
        boolean[] marked = new boolean[n];
        long unmarkedSum = 0;
        for (int num : nums) {
            unmarkedSum += num;
        }

        for (int i = 0; i < m; i++) {
            int index = queries[i][0];
            int k = queries[i][1];

            if (!marked[index]) {
                marked[index] = true;
                unmarkedSum -= nums[index];
            }

            PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> {
                if (nums[a] != nums[b]) {
                    return nums[a] - nums[b];
                } else {
                    return a - b;
                }
            });

            for (int j = 0; j < n; j++) {
                if (!marked[j]) {
                    pq.offer(j);
                }
            }

            int count = 0;
            while (!pq.isEmpty() && count < k) {
                int j = pq.poll();
                marked[j] = true;
                unmarkedSum -= nums[j];
                count++;
            }

            answer[i] = unmarkedSum;
        }

        return answer;
    }
}

