public class Solution {
    public int minOrAfterOperations(int[] nums, int k) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        if (k >= n - 1) {
            int result = 0;
            for (int num : nums) {
                result |= num;
            }
            return result;
        }

        int minOr = Integer.MAX_VALUE;
        for (int i = 0; i < (1 << (n - 1)); i++) {
            if (Integer.bitCount(i) > k) {
                continue;
            }

            int[] currentNums = new int[n - Integer.bitCount(i)];
            int index = 0;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) == 0) {
                    currentNums[index++] = nums[j];
                } else {
                    if (j + 1 < n) {
                        nums[j] &= nums[j + 1];
                    }
                }
            }

            int currentOr = 0;
            for (int num : nums) {
                if (num != 0) {
                    currentOr |= num;
                }
            }

            if (currentOr != 0) {
                minOr = Math.min(minOr, currentOr);
            }
        }

        if (minOr == Integer.MAX_VALUE) {
            int result = 0;
            for (int num : nums) {
                result |= num;
            }
            return result;
        }

        return minOr;
    }
}

