import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int mostFrequentPrime(int[][] mat) {
        Map<Integer, Integer> primeCounts = new HashMap<>();
        int rows = mat.length;
        int cols = mat[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                dfs(mat, i, j, "", primeCounts);
            }
        }

        int maxFrequency = 0;
        int mostFrequentPrime = -1;

        for (Map.Entry<Integer, Integer> entry : primeCounts.entrySet()) {
            int prime = entry.getKey();
            int frequency = entry.getValue();

            if (frequency > maxFrequency) {
                maxFrequency = frequency;
                mostFrequentPrime = prime;
            } else if (frequency == maxFrequency && prime > mostFrequentPrime) {
                mostFrequentPrime = prime;
            }
        }

        return mostFrequentPrime;
    }

    private void dfs(int[][] mat, int row, int col, String currentNumber, Map<Integer, Integer> primeCounts) {
        if (row < 0 || row >= mat.length || col < 0 || col >= mat[0].length) {
            return;
        }

        currentNumber += mat[row][col];
        int num = Integer.parseInt(currentNumber);

        if (num > 10 && isPrime(num)) {
            primeCounts.put(num, primeCounts.getOrDefault(num, 0) + 1);
        }

        // Explore all 8 directions
        dfs(mat, row + 1, col, currentNumber, primeCounts); // South
        dfs(mat, row - 1, col, currentNumber, primeCounts); // North
        dfs(mat, row, col + 1, currentNumber, primeCounts); // East
        dfs(mat, row, col - 1, currentNumber, primeCounts); // West
        dfs(mat, row + 1, col + 1, currentNumber, primeCounts); // South-East
        dfs(mat, row + 1, col - 1, currentNumber, primeCounts); // South-West
        dfs(mat, row - 1, col + 1, currentNumber, primeCounts); // North-East
        dfs(mat, row - 1, col - 1, currentNumber, primeCounts); // North-West
    }

    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

