            boolean changed = false;
            if (list.size() < 2) {
                break;
            }
            for (int i = 0; i < list.size(); i++) {
                for (int j = i + 1; j < list.size(); j++) {
                    if (list.get(i) > 0 && list.get(j) > 0) {
                        int mod = list.get(i) % list.get(j);
                        list.add(mod);
                        list.remove(j);
                        list.remove(i);
                        changed = true;
                        break;
                    }
                }
                if (changed) {
                    break;
                }
            }
            if (!changed) {
                break;
            }
        }

        return list.size();
    }
