import java.util.HashMap;
import java.util.Map;
public class Solution {
    public int maximumLength(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        int maxLen = 0;
        for (int base : counts.keySet()) {
            int len = 0;
            int power = 0;
            int currentCount = counts.get(base);

            while (currentCount > 0) {
                int neededCount = 1;
                if (power > 0) {
                    neededCount = 1;
                }

                if (currentCount >= neededCount) {
                    currentCount -= neededCount;
                    len++;
                    power++;
                } else {
                    break;
                }
            }

            int decreasingPower = power - 1;
            while (decreasingPower > 0) {
                int neededCount = 1;
                if (counts.containsKey((int)Math.pow(base, decreasingPower))) {
                    int availableCount = counts.get((int)Math.pow(base, decreasingPower));
                    if (availableCount > 0) {
                        counts.put((int)Math.pow(base, decreasingPower), availableCount - 1);
                        len++;
                        decreasingPower--;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }

            maxLen = Math.max(maxLen, len);
        }

        return maxLen;
    }
}

