import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[][] resultGrid(int[][] image, int threshold) {
        int m = image.length;
        int n = image[0].length;
        int[][] result = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                List<List<Integer>> regions = new ArrayList<>();

                // Check 3x3 neighborhood
                for (int row = Math.max(0, i - 1); row <= Math.min(m - 1, i + 1); row++) {
                    for (int col = Math.max(0, j - 1); col <= Math.min(n - 1, j + 1); col++) {
                        if (Math.abs(image[i][j] - image[row][col]) <= threshold) {
                            List<Integer> region = new ArrayList<>();
                            boolean found = false;
                            for (List<Integer> existingRegion : regions) {
                                if (existingRegion.contains(row * n + col)) {
                                    existingRegion.add(i * n + j);
                                    found = true;
                                    break;
                                }
                            }
                            if (!found) {
                                region.add(row * n + col);
                                region.add(i * n + j);
                                regions.add(region);
                            }
                        }
                    }
                }

                if (regions.isEmpty()) {
                    result[i][j] = image[i][j];
                } else {
                    long sum = 0;
                    int count = 0;
                    for (List<Integer> region : regions) {
                        long regionSum = 0;
                        int regionCount = 0;
                        for (int pixel : region) {
                            int row = pixel / n;
                            int col = pixel % n;
                            regionSum += image[row][col];
                            regionCount++;
                        }
                        sum += regionSum / regionCount;
                        count++;
                    }
                    result[i][j] = (int) (sum / count);
                }
            }
        }

        return result;
    }
}

