public class Solution {
    public int minimumOperationsToWriteY(int[][] arr) {
        int n = arr.length;
        int center = n / 2;
        int operations = 0;

        // Check values on the Y
        int yValue = arr[0][center];
        for (int i = 0; i < n; i++) {
            if (arr[i][center] != yValue) {
                operations++;
            }
        }
        for (int i = 0; i <= center; i++) {
            if (arr[i][i] != yValue) {
                operations++;
            }
            if (arr[i][n - 1 - i] != yValue) {
                operations++;
            }
        }

        // Check values not on the Y
        int notYValue = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != center && (j != i && j != n - 1 - i)) {
                    if (notYValue == -1) {
                        notYValue = arr[i][j];
                    } else if (arr[i][j] != notYValue) {
                        operations++;
                    }
                }
            }
        }

        if (yValue == notYValue) {
            operations = 0;
            int count0 = 0;
            int count1 = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == center || (j == i) || (j == n - 1 - i)) {
                        if (arr[i][j] == 0) {
                            count0++;
                        } else {
                            count0 = Integer.MAX_VALUE;
                            break;
                        }
                    } else {
                        if (arr[i][j] == 1) {
                            count1++;
                        } else {
                            count1 = Integer.MAX_VALUE;
                            break;
                        }
                    }
                }
            }
            if (count0 != Integer.MAX_VALUE && count1 != Integer.MAX_VALUE) {
                operations = 0;
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if ((i == center || (j == i) || (j == n - 1 - i)) && arr[i][j] != 0) {
                            operations++;
                        } else if ((i != center && (j != i && j != n - 1 - i)) && arr[i][j] != 1) {
                            operations++;
                        }
                    }
                }
            } else {
                operations = 0;
                int count0_1 = 0;
                int count1_0 = 0;
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i == center || (j == i) || (j == n - 1 - i)) {
                            if (arr[i][j] == 1) {
                                count0_1++;
                            }
                        } else {
                            if (arr[i][j] == 0) {
                                count1_0++;
                            }
                        }
                    }
                }
                operations = Math.min(count0_1, count1_0);
            }
        }

        return operations;
