import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] countPairsOfConnectableServers(int[][] edges, int signalSpeed) {
        int n = 0;
        for (int[] edge : edges) {
            n = Math.max(n, Math.max(edge[0], edge[1]) + 1);
        }

        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int weight = edge[2];
            adj.get(u).add(new int[]{v, weight});
            adj.get(v).add(new int[]{u, weight});
        }

        int[] count = new int[n];
        for (int i = 0; i < n; i++) {
            count[i] = 0;
            for (int j = i + 1; j < n; j++) {
                if (isConnectable(i, j, adj, signalSpeed)) {
                    count[i]++;
                }
            }
        }

        return count;
    }

    private boolean isConnectable(int a, int b, List<List<int[]>> adj, int signalSpeed) {
        List<Integer> pathA = new ArrayList<>();
        List<Integer> pathB = new ArrayList<>();

        if (!dfs(a, b, adj, signalSpeed, pathA, new boolean[adj.size()])) {
            return false;
        }

        if (!dfs(b, a, adj, signalSpeed, pathB, new boolean[adj.size()])) {
            return false;
        }


        for (int i = 0; i < pathA.size() - 1; i++) {
            int u = pathA.get(i);
            int v = pathA.get(i + 1);
            for (int j = 0; j < pathB.size() - 1; j++) {
                int x = pathB.get(j);
                int y = pathB.get(j + 1);
                if ((u == x && v == y) || (u == y && v == x)) {
                    return false;
                }
            }
        }

        return true;
    }

    private boolean dfs(int start, int end, List<List<int[]>> adj, int signalSpeed, List<Integer> path, boolean[] visited) {
        visited[start] = true;
        path.add(start);

        if (start == end) {
            return true;
        }

        for (int[] neighbor : adj.get(start)) {
            int v = neighbor[0];
            int weight = neighbor[1];
            if (!visited[v] && weight % signalSpeed == 0) {
                if (dfs(v, end, adj, signalSpeed, path, visited)) {
                    return true;
                }
            }
        }

        path.remove(path.size() - 1);
        return false;
    }
}

