        for (int num : nums) {
            int maxDigit = 0;
            int temp = num;
            while (temp > 0) {
                int digit = temp % 10;
                maxDigit = Math.max(maxDigit, digit);
                temp /= 10;
            }

            int encryptedNum = 0;
            temp = num;
            int numDigits = 0;
            while (temp > 0) {
                numDigits++;
                temp /= 10;
            }

            for (int i = 0; i < numDigits; i++) {
                encryptedNum = encryptedNum * 10 + maxDigit;
            }
            sum += encryptedNum;
        }
        return sum;
    }
