public class Solution {
    public int maxPartitionsAfterOperations(String s, int k) {
        int n = s.length();
        int maxPartitions = 0;

        // Try without any changes
        maxPartitions = calculatePartitions(s, k);

        // Try changing each character
        for (int i = 0; i < n; i++) {
            for (char c = 'a'; c <= 'z'; c++) {
                String temp = s.substring(0, i) + c + s.substring(i + 1);
                maxPartitions = Math.max(maxPartitions, calculatePartitions(temp, k));
            }
        }

        return maxPartitions;
    }

    private int calculatePartitions(String s, int k) {
        int partitions = 0;
        int start = 0;
        while (start < s.length()) {
            int end = start;
            Map<Character, Integer> charCount = new HashMap<>();
            int distinctChars = 0;
            while (end < s.length()) {
                char c = s.charAt(end);
                if (!charCount.containsKey(c)) {
                    distinctChars++;
                }
                charCount.put(c, charCount.getOrDefault(c, 0) + 1);
                if (distinctChars > k) {
                    break;
                }
                end++;
            }
            partitions++;
            start = end;
        }
        return partitions;
    }
}

