// #2024_02_28_Time_6_ms_(93.62%)_Space_60_MB_(56.71%)
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public long[] countOfPairs(int n, int x, int y) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int i = 1; i < n; i++) {
            adj.get(i).add(i + 1);
            adj.get(i + 1).add(i);
        }

        adj.get(x).add(y);
        adj.get(y).add(x);

        long[] result = new long[n + 1];

        for (int startNode = 1; startNode <= n; startNode++) {
            for (int endNode = 1; endNode <= n; endNode++) {
                if (startNode == endNode) continue;

                int distance = bfs(adj, startNode, endNode, n);
                if (distance != -1) {
                    result[distance]++;
                }
            }
        }

        return result;
    }

    private int bfs(List<List<Integer>> adj, int startNode, int endNode, int n) {
        int[] dist = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dist[i] = -1;
        }

        Queue<Integer> queue = new LinkedList<>();
        queue.offer(startNode);
        dist[startNode] = 0;

        while (!queue.isEmpty()) {
            int u = queue.poll();

            for (int v : adj.get(u)) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    queue.offer(v);
                }
            }
        }

        return dist[endNode];
    }
