        int len1 = s1.length();
        int len2 = s2.length();
        int i = len1 - 1;
        int j = len2 - 1;
        int count = 0;
        while (i >= 0 && j >= 0 && s1.charAt(i) == s2.charAt(j)) {
            count++;
            i--;
            j--;
        }
        return count;
    }
}

