public class Solution {
    public long maximumStrength(int[] n, int k) {
        int len = n.length;
        long[][] dp = new long[k + 1][len + 1];

        for (int i = 1; i <= k; i++) {
            for (int j = 1; j <= len; j++) {
                long currentStrength = 0;
                for (int x = 1; x <= j; x++) {
                    long sum = 0;
                    for (int l = 0; l < x; l++) {
                        sum += n[j - 1 - l];
                    }
                    long term = 0;
                    if ((x % 2) == 1) {
                        term = sum * (j - x + 1);
                    } else {
                        term = -sum * (j - x + 1);
                    }
                    currentStrength += term;
                }

                dp[i][j] = Math.max(dp[i][j - 1], dp[i - 1][j - 1] + currentStrength);
            }
        }

        return dp[k][len];
    }
}

