public class Solution {
    public long minimumCost(int[] nums, int k, int dist) {
        int n = nums.length;
        if (k == 1) {
            long cost = nums[0];
            return cost;
        }
        if (k >= n) {
            long cost = 0;
            for (int num : nums) {
                cost += num;
            }
            return cost;
        }

        long[][] dp = new long[k + 1][n + 1];
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = Long.MAX_VALUE;
            }
        }

        dp[0][0] = 0;

        for (int i = 1; i <= k; i++) {
            for (int j = i; j <= n; j++) {
                for (int l = i - 1; l < j; l++) {
                    if (dp[i - 1][l] != Long.MAX_VALUE) {
                        long cost = nums[l];
                        if (i == k && l - (i - 2) > dist && i > 1) {
                            continue;
                        }
                        dp[i][j] = Math.min(dp[i][j], dp[i - 1][l] + cost);
                    }
                }
            }
        }

        long minCost = Long.MAX_VALUE;
        for (int i = k; i <= n; i++) {
            minCost = Math.min(minCost, dp[k][i]);
        }

        return minCost;
    }
