import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
public class Solution {
    public int maxOperations(int[] nums) {
        int n = nums.length;
        if (n < 2) {
            return 0;
        }

        Map<Integer, Integer> dp = new HashMap<>();

        return solve(nums, 0, n - 1, dp);
    }

    private int solve(int[] nums, int left, int right, Map<Integer, Integer> dp) {
        if (left >= right) {
            return 0;
        }

        int key = (left << 10) | right;
        if (dp.containsKey(key)) {
            return dp.get(key);
        }

        int maxOps = 0;
        int score = nums[left] + nums[right];

        // Option 1: Delete first two elements
        if (right - left >= 1) {
            int nextLeft = left + 1;
            int nextRight = right;
            int currentOps = 1;
            if (currentOps == 1 && nums[left] + nums[left + 1] == score) {
                maxOps = Math.max(maxOps, currentOps + solve(nums, left + 2, right, dp));
            }
        }

        // Option 2: Delete last two elements
        if (right - left >= 1) {
            int nextLeft = left;
            int nextRight = right - 1;
            int currentOps = 1;
            if (currentOps == 1 && nums[right] + nums[right - 1] == score) {
                maxOps = Math.max(maxOps, currentOps + solve(nums, left, right - 2, dp));
            }
        }

        // Option 3: Delete first and last elements
        if (right - left >= 1) {
            int nextLeft = left + 1;
            int nextRight = right - 1;
            int currentOps = 1;
            if (currentOps == 1 && nums[left] + nums[right] == score) {
                maxOps = Math.max(maxOps, currentOps + solve(nums, left + 1, right - 1, dp));
            }
        }

        dp.put(key, maxOps);
        return maxOps;
    }
}

