public class Solution {
    public int minimumTimeToInitialState(String w, int q) {
        int n = w.length();
        if (n == 0) {
            return 0;
        }

        long hash = 0;
        long power = 1;
        int base = 31;
        int mod = 1000000007;

        for (int i = 0; i < n; i++) {
            hash = (hash * base + w.charAt(i)) % mod;
        }

        long initialHash = hash;
        int time = 0;

        if (initialHash == 0) return 0;

        while (true) {
            time++;

            String removed = w.substring(0, q);
            String added = "";
            for (int i = 0; i < q; i++) {
                added += 'a';
            }

            w = w.substring(q) + added;

            hash = 0;
            for (int i = 0; i < n; i++) {
                hash = (hash * base + w.charAt(i)) % mod;
            }

            if (hash == initialHash && w.equals(new String(new char[n]).replace('\0', 'a'))) {
                break;
            }

            if (time > n) {
                return -1;
            }
        }

        return time;
    }
