        int n = nums.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }

        Arrays.sort(indices, (a, b) -> {
            int bitsA = Integer.bitCount(nums[a]);
            int bitsB = Integer.bitCount(nums[b]);
            if (bitsA != bitsB) {
