        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int i = 0; i < n; i++) {
            if (parents[i] != -1) {
                adj.get(parents[i]).add(i);
            }
        }

        Map<Integer, Long> nodeScores = new HashMap<>();
        calculateScores(0, adj, nodeScores);

        long maxScore = 0;
        for (long score : nodeScores.values()) {
            maxScore = Math.max(maxScore, score);
        }

        int count = 0;
        for (long score : nodeScores.values()) {
            if (score == maxScore) {
                count++;
            }
        }

        return count;
    }

    private long calculateScores(int node, List<List<Integer>> adj, Map<Integer, Long> nodeScores) {
        long score = 1;
        for (int child : adj.get(node)) {
            score *= calculateScores(child, adj, nodeScores);
        }
        nodeScores.put(node, score);
        return score;
    }
}

