public class Solution {
    public int minCost(int[] startPos, int[] homePos, int[] rowCosts, int[] colCosts) {
        int startRow = startPos[0];
        int startCol = startPos[1];
        int homeRow = homePos[0];
        int homeCol = homePos[1];

        int cost = 0;

        // Calculate cost for row movement
        if (startRow < homeRow) {
            for (int i = startRow + 1; i <= homeRow; i++) {
                cost += rowCosts[i];
            }
        } else if (startRow > homeRow) {
            for (int i = startRow - 1; i >= homeRow; i--) {
                cost += rowCosts[i];
            }
        }

        // Calculate cost for column movement
        if (startCol < homeCol) {
            for (int i = startCol + 1; i <= homeCol; i++) {
                cost += colCosts[i];
            }
        } else if (startCol > homeCol) {
            for (int i = startCol - 1; i >= homeCol; i--) {
                cost += colCosts[i];
            }
        }

        return cost;
    }
}

