import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;
public class Solution {
    // 0: rook, queen, bishop
    public int countCombinations(String[] pieces, int[][] positions) {
        int n = pieces.length;
        ArrayList<int[]> destinations = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            destinations.add(new int[]{positions[i][0], positions[i][1]});
        }
        return solve(pieces, positions, destinations, 0);
    }

    private int solve(String[] pieces, int[][] positions, ArrayList<int[]> destinations, int index) {
        if (index == pieces.length) {
            if (isValid(positions)) {
                return 1;
            } else {
                return 0;
            }
        }

        int count = 0;
        String pieceType = pieces[index];
        int row = positions[index][0];
        int col = positions[index][1];

        ArrayList<int[]> possibleDestinations = getPossibleDestinations(row, col, pieceType);

        for (int[] destination : possibleDestinations) {
            int newRow = destination[0];
            int newCol = destination[1];

            positions[index][0] = newRow;
            positions[index][1] = newCol;

            count += solve(pieces, positions, destinations, index + 1);

            positions[index][0] = row;
            positions[index][1] = col;
        }

        return count;
    }

    private ArrayList<int[]> getPossibleDestinations(int row, int col, String pieceType) {
        ArrayList<int[]> destinations = new ArrayList<>();
        if (pieceType.equals("rook")) {
            addDestination(destinations, row + 1, col);
            addDestination(destinations, row - 1, col);
            addDestination(destinations, row, col + 1);
            addDestination(destinations, row, col - 1);
        } else if (pieceType.equals("queen")) {
            addDestination(destinations, row + 1, col);
            addDestination(destinations, row - 1, col);
            addDestination(destinations, row, col + 1);
            addDestination(destinations, row, col - 1);
            addDestination(destinations, row + 1, col + 1);
            addDestination(destinations, row + 1, col - 1);
            addDestination(destinations, row - 1, col + 1);
            addDestination(destinations, row - 1, col - 1);
        } else {
            addDestination(destinations, row + 1, col + 1);
            addDestination(destinations, row + 1, col - 1);
            addDestination(destinations, row - 1, col + 1);
            addDestination(destinations, row - 1, col - 1);
        }
        destinations.add(new int[]{row, col});
        return destinations;
    }

    private void addDestination(ArrayList<int[]> destinations, int row, int col) {
        if (row >= 1 && row <= 8 && col >= 1 && col <= 8) {
            destinations.add(new int[]{row, col});
        }
    }

    private boolean isValid(int[][] positions) {
        Set<String> occupied = new HashSet<>();
        for (int[] pos : positions) {
            String key = pos[0] + "," + pos[1];
            if (occupied.contains(key)) {
                return false;
            }
            occupied.add(key);
        }
        return true;
    }
}

