public class Solution {
    public boolean placeWordInCrossword(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceHorizontal(board, word, i, j)) {
                    return true;
                }
                if (canPlaceVertical(board, word, i, j)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canPlaceHorizontal(char[][] board, String word, int row, int col) {
        int wordLength = word.length();
        int n = board[0].length;

        if (col + wordLength > n) {
            return false;
        }

        for (int i = 0; i < wordLength; i++) {
            char boardChar = board[row][col + i];
            char wordChar = word.charAt(i);

            if (boardChar == '#' || (boardChar != ' ' && boardChar != wordChar)) {
                return false;
            }
        }

        if (col > 0 && board[row][col - 1] != '#') {
            return false;
        }
        if (col + wordLength < n && board[row][col + wordLength] != '#') {
            return false;
        }

        return true;
    }

    private boolean canPlaceVertical(char[][] board, String word, int row, int col) {
        int wordLength = word.length();
        int m = board.length;

        if (row + wordLength > m) {
            return false;
        }

        for (int i = 0; i < wordLength; i++) {
            char boardChar = board[row + i][col];
            char wordChar = word.charAt(i);

            if (boardChar == '#' || (boardChar != ' ' && boardChar != wordChar)) {
                return false;
            }
        }

        if (row > 0 && board[row - 1][col] != '#') {
            return false;
        }
        if (row + wordLength < m && board[row + wordLength][col] != '#') {
            return false;
        }

        return true;
    }
}

