public class Solution {

    static class Node {
        int index;
        int time;

        public Node(int index, int time) {
            this.index = index;
            this.time = time;
        }
    }

    public int maxQuality(int[] values, int[][] edges, int maxTime) {
        List<List<Node>> adj = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int time = edge[2];
            adj.get(u).add(new Node(v, time));
            adj.get(v).add(new Node(u, time));
        }

        int maxQuality = 0;
        Set<Integer> visited = new HashSet<>();
        maxQuality = dfs(0, 0, visited, values, adj, maxTime);

        return maxQuality;
    }

    private int dfs(int node, int currentTime, Set<Integer> visited, int[] values, List<List<Node>> adj, int maxTime) {
        visited.add(node);
        int quality = values[node];

        int maxQuality = quality;

        for (Node neighbor : adj.get(node)) {
            if (currentTime + neighbor.time <= maxTime) {
                Set<Integer> newVisited = new HashSet<>(visited);
                if (!newVisited.contains(neighbor.index)) {
                    maxQuality = Math.max(maxQuality, quality + dfs(neighbor.index, currentTime + neighbor.time, newVisited, values, adj, maxTime));
                }
            }
        }

        if (node == 0 && currentTime > 0) {
            return quality;
        }

        return quality;
    }
}

