import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
public class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        int maxWays = 0;

        // Calculate ways without changing any element
        maxWays = Math.max(maxWays, countWays(nums));

        // Try changing each element to k and calculate ways
        for (int i = 0; i < n; i++) {
            int originalValue = nums[i];
            nums[i] = k;
            maxWays = Math.max(maxWays, countWays(nums));
            nums[i] = originalValue; // Restore original value
        }

        return maxWays;
    }

    private int countWays(int[] nums) {
        int n = nums.length;
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        int ways = 0;
        int leftSum = 0;
        for (int i = 0; i < n - 1; i++) {
            leftSum += nums[i];
            int rightSum = totalSum - leftSum;
            if (leftSum == rightSum) {
                ways++;
            }
        }
        return ways;
    }
}

