public class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        if (start == goal) {
            return 0;
        }

        Queue<Integer> queue = new LinkedList<>();
        queue.offer(start);

        HashSet<Integer> visited = new HashSet<>();
        visited.add(start);

        int operations = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int current = queue.poll();

                for (int num : nums) {
                    int next1 = current + num;
                    if (next1 == goal) {
                        return operations + 1;
                    }
                    if (next1 >= 0 && next1 <= 1000 && !visited.contains(next1)) {
                        queue.offer(next1);
                        visited.add(next1);
                    }

                    int next2 = current - num;
                    if (next2 == goal) {
                        return operations + 1;
                    }
                    if (next2 >= 0 && next2 <= 1000 && !visited.contains(next2)) {
                        queue.offer(next2);
                        visited.add(next2);
                    }

                    int next3 = current ^ num;
                    if (next3 == goal) {
                        return operations + 1;
                    }
                    if (next3 >= 0 && next3 <= 1000 && !visited.contains(next3)) {
                        queue.offer(next3);
                        visited.add(next3);
                    }
                }
            }
            operations++;
        }

        return -1;
    }
