import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
public class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length / 2;
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        List<Integer> subset = new ArrayList<>();
        int minDiff = Integer.MAX_VALUE;
        findSubset(nums, 0, 0, n, subset, sum, minDiff);
        return findSubset(nums, 0, 0, n, subset, sum, Integer.MAX_VALUE);
    }

    private int findSubset(int[] nums, int index, int currentSum, int n, List<Integer> subset, int totalSum, int minDiff) {
        if (subset.size() == n) {
            int diff = Math.abs(totalSum - 2 * currentSum);
            return diff;
        }

        if (index == nums.length) {
            return Integer.MAX_VALUE;
        }

        int include = Integer.MAX_VALUE;
        if (subset.size() < n) {
            subset.add(nums[index]);
            include = findSubset(nums, index + 1, currentSum + nums[index], n, subset, totalSum, minDiff);
            subset.remove(subset.size() - 1);
        }

        int exclude = findSubset(nums, index + 1, currentSum, n, subset, totalSum, minDiff);

        return Math.min(include, exclude);
    }
}

