            int right = n - 1;
            int result = 0;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (items[mid][0] <= query) {
                    result = maxBeauty[mid];
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            answer[i] = result;
        }
        return answer;
    }
