public class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int m = rolls.length;
        long sumRolls = 0;
        for (int roll : rolls) {
            sumRolls += roll;
        }

        long totalSum = (long) mean * (n + m);
        long missingSum = totalSum - sumRolls;

        if (missingSum < n || missingSum > 6 * n) {
            return new int[0];
        }

        int base = (int) (missingSum / n);
        int remainder = (int) (missingSum % n);

        int[] missing = new int[n];
        for (int i = 0; i < n; i++) {
            missing[i] = base;
            if (i < remainder) {
                missing[i]++;
            }
        }

        return missing;
    }
}

