public class Solution {
    public int maxProduct(String s) {
        int n = s.length();
        int maxProduct = 0;

        for (int i = 0; i < (1 << n); i++) {
            List<Character> seq1 = new ArrayList<>();
            List<Integer> indices1 = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    seq1.add(s.charAt(j));
                    indices1.add(j);
                }
            }

            if (!isPalindrome(seq1)) continue;

            List<Character> seq2 = new ArrayList<>();
            List<Integer> indices2 = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (!indices1.contains(j)) {
                    seq2.add(s.charAt(j));
                    indices2.add(j);
                }
            }

            if (isPalindrome(seq2)) {
                maxProduct = Math.max(maxProduct, seq1.size() * seq2.size());
            }
        }

        return maxProduct;
    }

    private boolean isPalindrome(List<Character> seq) {
        int left = 0;
        int right = seq.size() - 1;
        while (left < right) {
            if (!seq.get(left).equals(seq.get(right))) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

