public class Solution {
    public int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int i = 0; i < n; i++) {
            if (parents[i] != -1) {
                adj.get(parents[i]).add(i);
            }
        }

        int[] ans = new int[n];
        dfs(0, adj, nums, ans);
        return ans;
    }

    private void dfs(int node, List<List<Integer>> adj, int[] nums, int[] ans) {
        Set<Integer> subtreeValues = new HashSet<>();
        subtreeValues.add(nums[node]);

        for (int child : adj.get(node)) {
            dfs(child, adj, nums, ans);
            Set<Integer> childValues = getSubtreeValues(child, adj, nums);
            subtreeValues.addAll(childValues);
        }

        int missing = 1;
        while (subtreeValues.contains(missing)) {
            missing++;
        }
        ans[node] = missing;
    }

    private Set<Integer> getSubtreeValues(int node, List<List<Integer>> adj, int[] nums) {
        Set<Integer> subtreeValues = new HashSet<>();
        subtreeValues.add(nums[node]);

        for (int child : adj.get(node)) {
            Set<Integer> childValues = getSubtreeValues(child, adj, nums);
            subtreeValues.addAll(childValues);
        }

        return subtreeValues;
    }
}

