import com_github_leetcode.ListNode;
public class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;
        int groupLength = 1;
        while (head != null) {
            int count = 0;
            ListNode groupHead = head;
            ListNode groupTail = null;
            while (head != null && count < groupLength) {
                groupTail = head;
                head = head.next;
                count++;
            }
            if (count % 2 == 0) {
                ListNode reversedGroupHead = reverseList(groupHead, groupTail);
                prev.next = reversedGroupHead;
                groupHead.next = head;
                prev = groupHead;
            } else {
                prev.next = groupHead;
                prev = groupTail;
            }
            groupLength++;
        }
        return dummy.next;
    }

    private ListNode reverseList(ListNode head, ListNode tail) {
        ListNode prev = null;
        ListNode curr = head;
        ListNode next = null;
        while (curr != null && curr != tail.next) {
            next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}

