// #Medium #Array #String #Binary_Search #Prefix_Sum
// #2022_05_26_Time_10_ms_(92.49%)_Space_164.8_MB_(5.53%)
public class Solution {
    public int[] platesBetweenCandles(String s, int[][] queries) {
        int n = s.length();
        int[] candleIndices = new int[n];
        int candleCount = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '|') {
                candleIndices[candleCount++] = i;
            }
        }

        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + (s.charAt(i) == ' ' ? 1 : 0);
        }

        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];

            int startCandleIndex = -1;
            int endCandleIndex = -1;

            // Find the first candle index greater than or equal to left
            int low = 0;
            int high = candleCount - 1;
            while (low <= high) {
                int mid = (low + high) / 2;
                if (candleIndices[mid] >= left) {
                    startCandleIndex = candleIndices[mid];
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }

            // Find the last candle index less than or equal to right
            low = 0;
            high = candleCount - 1;
            while (low <= high) {
                int mid = (low + high) / 2;
                if (candleIndices[mid] <= right) {
                    endCandleIndex = candleIndices[mid];
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            if (startCandleIndex == -1 || endCandleIndex == -1 || startCandleIndex >= endCandleIndex) {
                result[i] = 0;
            } else {
                int plates = prefixSum[endCandleIndex + 1] - prefixSum[startCandleIndex];
                result[i] = plates;
            }
        }

        return result;
    }
}

