import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int[][] validArrangement(int[][] pairs) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        Map<Integer, Integer> inDegree = new HashMap<>();
        Map<Integer, Integer> outDegree = new HashMap<>();

        for (int[] pair : pairs) {
            int start = pair[0];
            int end = pair[1];

            graph.computeIfAbsent(start, k -> new ArrayList<>()).add(end);

            inDegree.put(end, inDegree.getOrDefault(end, 0) + 1);
            outDegree.put(start, outDegree.getOrDefault(start, 0) + 1);
        }

        int startNode = -1;
        for (int node : graph.keySet()) {
            if (outDegree.getOrDefault(node, 0) - inDegree.getOrDefault(node, 0) == 1) {
                startNode = node;
                break;
            }
        }

        if (startNode == -1) {
            for (int node : graph.keySet()) {
                startNode = node;
                break;
            }
        }

        List<Integer> resultList = new ArrayList<>();
        dfs(startNode, graph, resultList);

        int[][] result = new int[resultList.size()][2];
        for (int i = 0; i < resultList.size(); i++) {
            result[i][0] = resultList.get(i);
            if (i + 1 < resultList.size()) {
                result[i][1] = resultList.get(i + 1);
            } else {
                result[i][1] = -1;
            }
        }

        return result;
    }

    private void dfs(int node, Map<Integer, List<Integer>> graph, List<Integer> resultList) {
        while (graph.containsKey(node) && !graph.get(node).isEmpty()) {
            int nextNode = graph.get(node).remove(0);
            dfs(nextNode, graph, resultList);
        }
        resultList.add(0, node);
    }
}

