// #Medium #Linked_List #2022_05_27_Time_4_ms_(100.00%)_Space_63.7_MB_(88.92%)
import com_github_leetcode.ListNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        List<Integer> criticalPoints = new ArrayList<>();
        ListNode curr = head;
        int index = 0;

        while (curr != null && curr.next != null && curr.next.next != null) {
            if ((curr.val > curr.next.val && curr.val > curr.next.next.val) ||
                    (curr.val < curr.next.val && curr.val < curr.next.next.val)) {
                criticalPoints.add(index);
            }
            curr = curr.next;
            index++;
        }

        if (criticalPoints.size() < 2) {
            return new int[]{-1, -1};
        }

        int minDistance = Integer.MAX_VALUE;
        int maxDistance = 0;

        for (int i = 0; i < criticalPoints.size() - 1; i++) {
            int distance = criticalPoints.get(i + 1) - criticalPoints.get(i);
            minDistance = Math.min(minDistance, distance);
            maxDistance = Math.max(maxDistance, distance);
        }

        return new int[]{minDistance, maxDistance};
    }
}

