public class Solution {
    public long gridGame(int[][] grid) {
        int n = grid[0].length;
        long[] top = new long[n];
        long[] bottom = new long[n];

        top[n - 1] = grid[0][n - 1];
        for (int i = n - 2; i >= 0; i--) {
            top[i] = top[i + 1] + grid[0][i];
        }

        bottom[0] = grid[1][0];
        for (int i = 1; i < n; i++) {
            bottom[i] = bottom[i - 1] + grid[1][i];
        }

        long ans = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            long topVal = (i == 0) ? 0 : top[i - 1];
            long bottomVal = (i == n - 1) ? 0 : bottom[n - 1 - i];
            ans = Math.min(ans, Math.max(topVal, bottomVal));
        }

        return ans;
    }
}

