public class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int count = 0;

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    // Check for pyramids
                    for (int h = 2; r + h - 1 < m; h++) {
                        boolean validPyramid = true;
                        for (int i = r; i < r + h; i++) {
                            for (int j = c - (i - r); j <= c + (i - r); j++) {
                                if (j < 0 || j >= n || grid[i][j] == 0) {
                                    validPyramid = false;
                                    break;
                                }
                            }
                            if (!validPyramid) break;
                        }
                        if (validPyramid) count++;
                    }

                    // Check for inverse pyramids
                    for (int h = 2; r - h + 1 >= 0; h++) {
                        boolean validInversePyramid = true;
                        for (int i = r; i >= r - h + 1; i--) {
                            for (int j = c - (r - i); j <= c + (r - i); j++) {
                                if (j < 0 || j >= n || grid[i][j] == 0) {
                                    validInversePyramid = false;
                                    break;
                                }
                            }
                            if (!validInversePyramid) break;
                        }
                        if (validInversePyramid) count++;
                    }
                }
            }

        return count;
    }
}

