import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public String shortestPath(TreeNode root, int startValue, int destValue) {
        Map<Integer, TreeNode> nodeMap = new HashMap<>();
        buildNodeMap(root, nodeMap);

        TreeNode startNode = nodeMap.get(startValue);
        TreeNode destNode = nodeMap.get(destValue);

        List<String> path = new ArrayList<>();
        findPath(startNode, destNode, "", path);

        return String.join("", path);
    }

    private void buildNodeMap(TreeNode root, Map<Integer, TreeNode> nodeMap) {
        if (root == null) {
            return;
        }
        nodeMap.put(root.val, root);
        buildNodeMap(root.left, nodeMap);
        buildNodeMap(root.right, nodeMap);
    }

    private boolean findPath(TreeNode current, TreeNode dest, String currentPath, List<String> path) {
        if (current == null) {
            return false;
        }

        if (current.val == dest.val) {
            path.addAll(splitPath(currentPath));
            return true;
        }

        // Go left
        if (current.left != null) {
            if (findPath(current.left, dest, currentPath + "L", path)) {
                return true;
            }
        }

        // Go right
        if (current.right != null) {
            if (findPath(current.right, dest, currentPath + "R", path)) {
                return true;
            }
        }

        // Go up
        if (current.val != 1) {
            if (findPath(findParent(1, current), dest, currentPath + "U", path)) {
                return true;
            }
        }

        return false;
    }

    private TreeNode findParent(int rootVal, TreeNode child) {
        if (child == null) {
            return null;
        }
        if (child.val == rootVal) {
            return null;
        }

        return findParentHelper(rootVal, child);
    }

    private TreeNode findParentHelper(int rootVal, TreeNode child) {
        if (child == null) {
            return null;
        }

        if (child.left == null && child.right == null) {
            return null;
        }

        if (child.left != null && child.left.val == child.val) {
            return null;
        }

        if (child.right != null && child.right.val == child.val) {
            return null;
        }

        return findParentRecursive(1, child);
    }

    private TreeNode findParentRecursive(int rootVal, TreeNode child) {
        if (child == null) {
            return null;
        }

        if (child.left == null && child.right == null) {
            return null;
        }

        if (child.left != null && child.left.val == child.val) {
            return null;
        }

        if (child.right != null && child.right.val == child.val) {
            return null;
        }

        return findParentRecursiveHelper(1, child);
    }

    private TreeNode findParentRecursiveHelper(int rootVal, TreeNode child) {
        if (child == null) {
            return null;
        }

        if (child.left != null && child.left.val == child.val) {
            return null;
        }

        if (child.right != null && child.right.val == child.val) {
            return null;
        }

        return null;
    }

    private List<String> splitPath(String path) {
        List<String> result = new ArrayList<>();
        for (char c : path.toCharArray()) {
            result.add(String.valueOf(c));
        }
        return result;
    }
}

