import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
public class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int[][] dist = new int[n + 1][2];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }
        dist[1][0] = 0;

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{1, 0});

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int node = curr[0];
            int count = curr[1];

            for (int neighbor : adj.get(node)) {
                int arrivalTime = dist[node][count] + time;
                int cycle = arrivalTime / change;
                if (cycle % 2 == 1) {
                    arrivalTime += change - (arrivalTime % change);
                }

                if (arrivalTime < dist[neighbor][0]) {
                    dist[neighbor][1] = dist[neighbor][0];
                    dist[neighbor][0] = arrivalTime;
                    queue.offer(new int[]{neighbor, 0});
                } else if (arrivalTime > dist[neighbor][0] && arrivalTime < dist[neighbor][1]) {
                    dist[neighbor][1] = arrivalTime;
                    queue.offer(new int[]{neighbor, 1});
                }
            }
        }

        return dist[n][1];
    }
}

