public class Solution {
    public int maxConsecutiveAnswers(String answerKey, int k) {
        int n = answerKey.length();
        int maxConsecutive = 0;

        // Calculate max consecutive 'T's
        int left = 0;
        int tCount = 0;
        for (int right = 0; right < n; right++) {
            if (answerKey.charAt(right) == 'T') {
                tCount++;
            }
            while (right - left + 1 - tCount > k) {
                if (answerKey.charAt(left) == 'T') {
                    tCount--;
                }
                left++;
            }
            maxConsecutive = Math.max(maxConsecutive, right - left + 1);
        }

        // Calculate max consecutive 'F's
        left = 0;
        int fCount = 0;
        for (int right = 0; right < n; right++) {
            if (answerKey.charAt(right) == 'F') {
                fCount++;
            }
            while (right - left + 1 - fCount > k) {
                if (answerKey.charAt(left) == 'F') {
                    fCount--;
                }
                left++;
            }
            maxConsecutive = Math.max(maxConsecutive, right - left + 1);
        }

        return maxConsecutive;
    }
}

