// #2022_05_30_Time_156_ms_(40.49%)_Space_117.1_MB_(61.46%)
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
public class Solution {
    public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        Arrays.sort(tasks);
        Arrays.sort(workers);
        int left = 0;
        int right = Math.min(tasks.length, workers.length);
        int ans = 0;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (check(tasks, workers, pills, strength, mid)) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return ans;
    }

    private boolean check(int[] tasks, int[] workers, int pills, int strength, int k) {
        int[] workerCopy = Arrays.copyOf(workers, workers.length);
        int[] taskCopy = Arrays.copyOf(tasks, tasks.length);
        int j = workers.length - 1;
        int i = tasks.length - 1;
        int remainingPills = pills;
        while (i >= tasks.length - k) {
            if (workerCopy[j] >= taskCopy[i]) {
                j--;
                i--;
            } else if (remainingPills > 0) {
                if (workerCopy[j] + strength >= taskCopy[i]) {
                    remainingPills--;
                    j--;
                    i--;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        }
        return true;
    }
}

