import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        // Initialize the first person and person 0 as knowing the secret
        union(parent, 0, firstPerson);

        // Sort meetings by time
        Arrays.sort(meetings, (a, b) -> a[2] - b[2]);

        int prevTime = -1;
        for (int[] meeting : meetings) {
            int x = meeting[0];
            int y = meeting[1];
            int time = meeting[2];

            if (time != prevTime) {
                // Reset the connected components for the current time
                for (int i = 0; i < n; i++) {
                    if (find(parent, i) != find(parent, 0)) {
                        parent[i] = i;
                    }
                }
            }

            union(parent, x, y);
            prevTime = time;
        }

        Set<Integer> knowsSecret = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (find(parent, i) == find(parent, 0)) {
                knowsSecret.add(i);
            }
        }

        return new ArrayList<>(knowsSecret);
    }

    private int find(int[] parent, int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent, parent[i]);
    }

    private void union(int[] parent, int x, int y) {
