import java.util.Arrays;
public class Solution {
    public int[] getAverages(int[] nums, int k) {
        int n = nums.length;
        int[] avgs = new int[n];
        Arrays.fill(avgs, -1);

        if (n < 2 * k + 1) {
            return avgs;
        }

        long windowSum = 0;
        for (int i = 0; i <= 2 * k; i++) {
            windowSum += nums[i];
        }

        avgs[k] = (int) (windowSum / (2 * k + 1));

        for (int i = k + 1; i < n; i++) {
            windowSum = windowSum - nums[i - k - 1] + nums[i];
            avgs[i] = (int) (windowSum / (2 * k + 1));
        }

        return avgs;
    }
}

