public class Solution {
    public long maxTaxiEarnings(int n, int[][] rides) {
        List<int[]> ridesList = new ArrayList<>();
        for (int[] ride : rides) {
            ridesList.add(ride);
        }
        ridesList.sort((a, b) -> a[1] - b[1]);
        long[] dp = new long[ridesList.size() + 1];
        dp[0] = 0;
        for (int i = 1; i <= ridesList.size(); i++) {
            int[] currentRide = ridesList.get(i - 1);
            long currentEarnings = currentRide[0] + currentRide[1] + currentRide[2];
            int prevRideIndex = -1;
            for (int j = i - 1; j >= 0; j--) {
                if (ridesList.get(j)[1] <= currentRide[0]) {
                    prevRideIndex = j;
                    break;
                }
            }
            long prevEarnings = (prevRideIndex == -1) ? 0 : dp[prevRideIndex + 1];
            dp[i] = Math.max(dp[i - 1], prevEarnings + currentEarnings);
        }
        return dp[ridesList.size()];
    }
}

