public class Solution {
    public long kthSmallestProduct(int[] nums1, int[] nums2, long k) {
        int n = nums1.length;
        int m = nums2.length;

        long low = -10000000000L;
        long high = 10000000000L;

        while (low < high) {
            long mid = low + (high - low) / 2;
            long count = 0;
            for (int i = 0; i < n; i++) {
                int left = 0;
                int right = m - 1;
                int index = -1;
                while (left <= right) {
                    int midIndex = left + (right - left) / 2;
                    if ((long) nums1[i] * nums2[midIndex] <= mid) {
                        index = midIndex;
                        left = midIndex + 1;
                    } else {
                        right = midIndex - 1;
                    }
                }
                if (index != -1) {
                    count += index + 1;
                }
            }

            if (count < k) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        return low;
    }
}

