public class Solution {
    public int minPushBox(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int playerRow = -1, playerCol = -1;
        int boxRow = -1, boxCol = -1;
        int targetRow = -1, targetCol = -1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'S') {
                    playerRow = i;
                    playerCol = j;
                } else if (grid[i][j] == 'B') {
                    boxRow = i;
                    boxCol = j;
                } else if (grid[i][j] == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        int[][][] visited = new int[m][n][m * n];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{playerRow, playerCol, boxRow, boxCol, 0});
        visited[playerRow][playerCol][boxRow * n + boxCol] = 1;

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int playerRow = curr[0];
            int playerCol = curr[1];
            int boxRow = curr[2];
            int boxCol = curr[3];
            int pushes = curr[4];

            if (boxRow == targetRow && boxCol == targetCol) {
                return pushes;
            }

            for (int[] dir : directions) {
                int newPlayerRow = playerRow + dir[0];
                int newPlayerCol = playerCol + dir[1];

                if (newPlayerRow >= 0 && newPlayerRow < m && newPlayerCol >= 0 && newPlayerCol < n && grid[newPlayerRow][newPlayerCol] != '#') {
                    if (newPlayerRow == boxRow && newPlayerCol == boxCol) {
                        int newBoxRow = boxRow + dir[0];
                        int newBoxCol = boxCol + dir[1];

                        if (newBoxRow >= 0 && newBoxRow < m && newBoxCol >= 0 && newBoxCol < n && grid[newBoxRow][newBoxCol] != '#' &&
                                visited[newPlayerRow][newPlayerCol][newBoxRow * n + newBoxCol] == 0) {
                            visited[newPlayerRow][newPlayerCol][newBoxRow * n + newBoxCol] = 1;
                            queue.offer(new int[]{newPlayerRow, newPlayerCol, newBoxRow, newBoxCol, pushes + 1});
                        }
                    } else {
                        if (visited[newPlayerRow][newPlayerCol][boxRow * n + boxCol] == 0) {
                            visited[newPlayerRow][newPlayerCol][boxRow * n + boxCol] = 1;
                            queue.offer(new int[]{newPlayerRow, newPlayerCol, boxRow, boxCol, pushes});
                        }
                    }
                }
            }
        }

        return -1;
    }
}

