import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int shortestPath(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        if (m == 1 && n == 1) {
            return 0;
        }

        int[][][] visited = new int[m][n][k + 1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                for (int l = 0; l <= k; l++) {
                    visited[i][j][l] = -1;
                }
            }
        }

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0, k, 0}); // x, y, remaining obstacles, steps
        visited[0][0][k] = 0;

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];
            int remainingObstacles = current[2];
            int steps = current[3];

            for (int[] dir : directions) {
                int newX = x + dir[0];
                int newY = y + dir[1];

                if (newX >= 0 && newX < m && newY >= 0 && newY < n) {
                    int newRemainingObstacles = remainingObstacles - grid[newX][newY];

                    if (newRemainingObstacles >= 0 && visited[newX][newY][newRemainingObstacles] == -1) {
                        if (newX == m - 1 && newY == n - 1) {
                            return steps + 1;
                        }

                        visited[newX][newY][newRemainingObstacles] = steps + 1;
                        queue.offer(new int[]{newX, newY, newRemainingObstacles, steps + 1});
                    }
                }
            }
        }

        return -1;
    }
}

