public class Solution {
    /**
     * An ugly number is a positive integer that is divisible by a, b, or c.
     * Given four integers n, a, b, and c, return the <code>n<sup>th</sup></code> ugly number.
     *
     * @param n the nth ugly number to find
     * @param a the first divisor
     * @param b the second divisor
     * @param c the third divisor
     * @return the nth ugly number
     */
    public int nthUglyNumber(int n, int a, int b, int c) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        HashSet<Long> seen = new HashSet<>();

        pq.offer(1L);
        seen.add(1L);

        long ugly = 1;
        for (int i = 0; i < n; i++) {
            ugly = pq.poll();

            long nextA = ugly * a;
            if (!seen.contains(nextA)) {
                pq.offer(nextA);
                seen.add(nextA);
            }

            long nextB = ugly * b;
            if (!seen.contains(nextB)) {
                pq.offer(nextB);
                seen.add(nextB);
            }

            long nextC = ugly * c;
            if (!seen.contains(nextC)) {
                pq.offer(nextC);
                seen.add(nextC);
            }
        }

        return (int) ugly;
    }
}

