public class Solution {
    public List<List<Integer>> reconstructMatrix(int upper, int lower, int[] colsum) {
        int n = colsum.length;
        List<List<Integer>> matrix = new ArrayList<>();
        for (int i = 0; i < 2; i++) {
            matrix.add(new ArrayList<>());
            for (int j = 0; j < n; j++) {
                matrix.get(i).add(0);
            }
        }

        int upperSum = 0;
        int lowerSum = 0;

        for (int i = 0; i < n; i++) {
            if (colsum[i] == 2) {
                matrix.get(0).set(i, 1);
                matrix.get(1).set(i, 1);
                upperSum++;
                lowerSum++;
            } else if (colsum[i] == 1) {
                if (upperSum < upper) {
                    matrix.get(0).set(i, 1);
                    upperSum++;
                } else {
                    matrix.get(1).set(i, 1);
                    lowerSum++;
                }
            } else if (colsum[i] == 0) {
                // Do nothing
            }
        }

        if (upperSum != upper || lowerSum != lower) {
            return new ArrayList<>();
        }

        return matrix;
    }
