public class Solution {
    public int countVowelPermutation(int n) {
        long mod = 1000000007;
        long[] a = new long[n + 1];
        long[] e = new long[n + 1];
        long[] i = new long[n + 1];
        long[] o = new long[n + 1];
        long[] u = new long[n + 1];

