        e[1] = 1;
        i[1] = 1;
        o[1] = 1;
        u[1] = 1;

        for (int j = 2; j <= n; j++) {
            a[j] = (e[j - 1]) % mod;
            e[j] = (a[j - 1] + i[j - 1]) % mod;
            i[j] = (e[j - 1] + o[j - 1]) % mod;
            o[j] = (i[j - 1] + u[j - 1]) % mod;
            u[j] = (o[j - 1]) % mod;
        }

        long result = (a[n] + e[n] + i[n] + o[n] + u[n]) % mod;
        return (int) result;
    }
