public class Solution {
    public int minFallingPathSum(int[][] grid) {
        int n = grid.length;
        int[] curr = new int[n];
        for (int i = 0; i < n; i++) {
            curr[i] = grid[0][i];
        }
        for (int i = 1; i < n; i++) {
            int[] next = new int[n];
            for (int j = 0; j < n; j++) {
                int minVal = Integer.MAX_VALUE;
                for (int k = 0; k < n; k++) {
                    if (k != j) {
                        minVal = Math.min(minVal, curr[k]);
                    }
                }
                next[j] = grid[i][j] + minVal;
            }
            curr = next;
        }
        int minSum = Integer.MAX_VALUE;
        for (int sum : curr) {
            minSum = Math.min(minSum, sum);
        }
        return minSum;
    }
}

