import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;
public class Solution {
    public int minFlips(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int[][] target = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                target[i][j] = 0;
            }
        }
        Queue<int[]> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        int steps = 0;
        String initialState = matrixToString(mat);
        if (initialState.equals(matrixToString(target))) {
            return 0;
        }
        queue.offer(new int[]{0, 0});
        visited.add(initialState);
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] curr = queue.poll();
                int row = curr[0];
                int col = curr[1];
                int[][] nextMat = flip(mat, row, col);
                String nextState = matrixToString(nextMat);
                if (nextState.equals(matrixToString(target))) {
                    return steps + 1;
                }
                if (!visited.contains(nextState)) {
                    visited.add(nextState);
                    queue.offer(new int[]{0, 0});
                }
            }
            steps++;
        }
        return -1;
    }

    private int[][] flip(int[][] mat, int row, int col) {
        int m = mat.length;
        int n = mat[0].length;
        int[][] newMat = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                newMat[i][j] = mat[i][j];
            }
        }
        newMat[row][col] = 1 - newMat[row][col];
        if (row > 0) {
            newMat[row - 1][col] = 1 - newMat[row - 1][col];
        }
        if (row < m - 1) {
            newMat[row + 1][col] = 1 - newMat[row + 1][col];
        }
        if (col > 0) {
            newMat[row][col - 1] = 1 - newMat[row][col - 1];
        }
        if (col < n - 1) {
            newMat[row][col + 1] = 1 - newMat[row][col + 1];
        }
        return newMat;
    }

    private String matrixToString(int[][] mat) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[0].length; j++) {
                sb.append(mat[i][j]);
            }
        }
        return sb.toString();
    }
}

