// #Medium #Array #String #Bit_Manipulation #Backtracking
// #2022_03_12_Time_9_ms_(88.28%)_Space_45.3_MB_(68.10%)
import java.util.List;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int maxLength(List<String> arr) {
        int maxLen = 0;
        backtrack(arr, 0, new StringBuilder(), new HashSet<>(), maxLen);
        return maxLen;
    }

    private void backtrack(List<String> arr, int index, StringBuilder current, Set<Character> chars, int maxLen) {
        if (index == arr.size()) {
            maxLen = Math.max(maxLen, current.length());
            return;
        }

        String str = arr.get(index);
        boolean canAdd = true;
        Set<Character> newChars = new HashSet<>(chars);

        for (char c : str.toCharArray()) {
            if (newChars.contains(c)) {
                canAdd = false;
                break;
            }
            newChars.add(c);
        }

        if (canAdd) {
            current.append(str);
            backtrack(arr, index + 1, current, newChars, Math.max(maxLen, current.length()));
            current.delete(current.length() - str.length(), current.length());
        }

        backtrack(arr, index + 1, current, chars, maxLen);
    }
}

