public class Solution {
    public int maxSumDivThree(int[] nums) {
        int[] dp = new int[3];
        dp[0] = 0;
        dp[1] = Integer.MIN_VALUE;
        dp[2] = Integer.MIN_VALUE;

        for (int num : nums) {
            int[] nextDp = new int[3];
            for (int i = 0; i < 3; i++) {
                nextDp[i] = dp[i];
            }

            int rem = num % 3;
            for (int i = 0; i < 3; i++) {
                int newRem = (i + rem) % 3;
                nextDp[newRem] = Math.max(nextDp[newRem], dp[i] + num);
            }

            dp = nextDp;
        }

        return dp[0];
    }
}

