import java.util.Arrays;
public class Solution {
    public int findBestValue(int[] arr, int target) {
        int left = 0;
        int right = 100000;
        int bestValue = 0;
        long minDiff = Long.MAX_VALUE;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            long sum = 0;
            for (int num : arr) {
                sum += Math.min(num, mid);
            }

            long diff = Math.abs(sum - target);

            if (diff < minDiff) {
                minDiff = diff;
                bestValue = mid;
            } else if (diff == minDiff) {
                bestValue = Math.min(bestValue, mid);
            }

            if (sum < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return bestValue;
    }
}

