public class Solution {
    public List<Integer> numOfBurgers(int tomatoSlices, int cheeseSlices) {
        List<Integer> result = new ArrayList<>();
        if (tomatoSlices == 0 && cheeseSlices == 0) {
            result.add(0);
            result.add(0);
            return result;
        }

        for (int jumbo = 0; jumbo <= tomatoSlices / 4; jumbo++) {
            int remainingTomato = tomatoSlices - 4 * jumbo;
            int remainingCheese = cheeseSlices - jumbo;

            if (remainingCheese >= 0 && remainingTomato >= 0 && remainingTomato % 2 == 0) {
                int small = remainingTomato / 2;
                if (small >= 0 && small == cheeseSlices - jumbo) {
                    result.add(jumbo);
                    result.add(small);
                    return result;
                }
            }
        }

        return new ArrayList<>();
    }
}

