// #Hard #Array #Dynamic_Programming #Sorting #Binary_Search
// #2022_03_12_Time_27_ms_(89.19%)_Space_73.8_MB_(49.40%)
import java.util.Arrays;
import java.util.Comparator;
public class Solution {
    public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = startTime.length;
        int[][] jobs = new int[n][3];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = startTime[i];
            jobs[i][1] = endTime[i];
            jobs[i][2] = profit[i];
        }

        Arrays.sort(jobs, Comparator.comparingInt(a -> a[1]));

        int[] dp = new int[n];
        dp[0] = jobs[0][2];

        for (int i = 1; i < n; i++) {
            int currentProfit = jobs[i][2];
            int prevJobIndex = findNonOverlappingJob(jobs, i);
            if (prevJobIndex != -1) {
                currentProfit += dp[prevJobIndex];
            }
            dp[i] = Math.max(dp[i - 1], currentProfit);
        }

        return dp[n - 1];
    }

    private int findNonOverlappingJob(int[][] jobs, int currentIndex) {
        int low = 0;
        int high = currentIndex - 1;
        int result = -1;

        while (low <= high) {
            int mid = (low + high) / 2;
            if (jobs[mid][1] <= jobs[currentIndex][0]) {
                result = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return result;
    }
}

