// #Hard #String #Dynamic_Programming #2022_03_12_Time_4_ms_(89.93%)_Space_42.6_MB_(30.60%)
import java.util.Arrays;
public class Solution {
    public int palindromePartition(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int l = 1; l <= i; l++) {
                    String sub = s.substring(i - l, i);
                    int cost = calculateCost(sub);
                    if (dp[i - l][j - 1] != Integer.MAX_VALUE) {
                        dp[i][j] = Math.min(dp[i][j], dp[i - l][j - 1] + cost);
                    }
                }
            }
        }

        return dp[n][k];
    }

    private int calculateCost(String s) {
        int cost = 0;
        int left = 0;
        int right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                cost++;
            }
            left++;
            right--;
        }
        return cost;
    }
}

