// #Medium #String #Sliding_Window #2022_03_12_Time_7_ms_(89.84%)_Space_44.4_MB_(33.77%)
public class Solution {
    public int balancedString(String s) {
        int n = s.length();
        int target = n / 4;
        int[] count = new int[4];
        for (char c : s.toCharArray()) {
            if (c == 'Q') count[0]++;
            else if (c == 'W') count[1]++;
            else if (c == 'E') count[2]++;
            else count[3]++;
        }

        int left = 0;
        int minLen = n;
        for (int right = 0; right < n; right++) {
            count[getIndex(s.charAt(right))]--;
            while (isValid(count, target)) {
                minLen = Math.min(minLen, right - left + 1);
                count[getIndex(s.charAt(left))]++;
                left++;
            }
        }

        return minLen;
    }

    private int getIndex(char c) {
        if (c == 'Q') return 0;
        else if (c == 'W') return 1;
        else if (c == 'E') return 2;
        else return 3;
    }

    private boolean isValid(int[] count, int target) {
        for (int i = 0; i < 4; i++) {
            if (count[i] > 0) return false;
        }
        return true;
    }
}
